from specflow.refmodel.temporal import after, edges, eventually, worst

def decide(trace):
    # No encoding table is provided for cmd.  A cmd transition is therefore
    # used only as the observable signature of receiving a new command.
    cmd_changes = edges(trace, "cmd", "change")
    windows = after(
        trace,
        lambda r: r["edge"] in cmd_changes,
        until=lambda r: r["outputs"].get("cmd_ack") == 1
    )

    control_ports = ("scl_o", "scl_oen", "sda_o", "sda_oen")

    def shows_control_activity(w):
        initial = tuple(w.value(port) for port in control_ports)
        return eventually(
            w,
            lambda r: tuple(r["outputs"].get(port) for port in control_ports) != initial,
            after_activation=True,
            strong=False
        )

    return worst([shows_control_activity(w) for w in windows])

def decide(trace):
    if not trace:
        return (None, None, 'no observable states; open-drain control was not exercised')

    for row in trace:
        outputs = row['outputs']
        edge = row['edge']
        if outputs.get('scl_o') != 0:
            return (False, edge, f"scl_o was {outputs.get('scl_o')!r}; open-drain drive value must remain low")
        if outputs.get('sda_o') != 0:
            return (False, edge, f"sda_o was {outputs.get('sda_o')!r}; open-drain drive value must remain low")
        for port in ('scl_oen', 'sda_oen'):
            value = outputs.get(port)
            if value not in (0, 1):
                return (False, edge, f"{port} was {value!r}; active-low output-enable controls must be 0 or 1")

    return (True, trace[-1]['edge'], 'scl_o and sda_o remained constant low; scl_oen and sda_oen remained valid active-low control levels')

def decide(trace):
    if not trace:
        return (None, None, 'no interface observation; module operation was not observed')

    for row in trace:
        outputs = row['outputs']
        bad = [p for p in ('scl_o', 'sda_o') if outputs.get(p) != 0]
        if bad:
            return (False, row['edge'],
                    f"{', '.join(bad)} is not constantly low; expected low drive value 0")

    return (True, trace[-1]['edge'],
            'scl_o and sda_o remained constantly low throughout the observed operation')

def decide(trace):
    relevant = []
    bad = []

    for row in trace:
        outputs = row.get('outputs', {})

        if outputs.get('scl_oen') in (0, 1):
            relevant.append((row, 'scl_oen', 'scl_o'))
            if outputs.get('scl_o') != 0:
                bad.append((row, 'scl_oen', outputs.get('scl_o')))

        if outputs.get('sda_oen') in (0, 1):
            relevant.append((row, 'sda_oen', 'sda_o'))
            if outputs.get('sda_o') != 0:
                bad.append((row, 'sda_oen', outputs.get('sda_o')))

    if not relevant:
        return (None, None,
                'no scl_oen or sda_oen control level occurred in the trace')

    if bad:
        row, enable, value = bad[0]
        drive = 'scl_o' if enable == 'scl_oen' else 'sda_o'
        return (False, row.get('edge'),
                f'{drive} was {value!r} while {enable} was evaluated; '
                'the corresponding constant-low drive must be 0')

    return (True, relevant[-1][0].get('edge'),
            'each observed output-enable level had the corresponding '
            'constant-low drive value 0')

def decide(trace):
    ports = ('scl_o', 'scl_oen', 'sda_o', 'sda_oen')

    def signature(row):
        return tuple(row['outputs'].get(port) for port in ports)

    activations = []
    for i in range(1, len(trace)):
        previous = trace[i - 1]
        row = trace[i]
        cmd_changed = row['inputs'].get('cmd') != previous['inputs'].get('cmd')
        busy_started = (previous['outputs'].get('busy') != 1 and
                        row['outputs'].get('busy') == 1)
        if row['outputs'].get('busy') == 1 and (cmd_changed or busy_started):
            activations.append(i)

    if not activations:
        return (None, None,
                'no command-driven control phase was observed after a command presentation')

    unknown_details = []
    for start in activations:
        start_cmd = trace[start]['inputs'].get('cmd')
        end = None
        changed = None

        for i in range(start, len(trace)):
            row = trace[i]
            if i > start:
                previous = trace[i - 1]
                if (row['outputs'].get('busy') != 1 or
                        row['inputs'].get('cmd') != start_cmd):
                    end = i
                    break
                if signature(row) != signature(previous):
                    changed = row
                    break
            else:
                if signature(row) != signature(trace[i - 1]):
                    changed = row
                    break

        if changed is not None:
            return (True, changed['edge'],
                    'at least one SCL/SDA control output changed during the command-driven control phase')

        if end is not None:
            return (False, trace[end - 1]['edge'],
                    'the command-driven control phase ended without a transition on scl_o, scl_oen, sda_o, or sda_oen')

        unknown_details.append(start)

    return (None, None,
            'the command-driven control phase was still open when the trace ended')

def decide(trace):
    if not trace:
        return (None, None, 'no sampled rising-edge states are present in the trace')

    previous = None
    observed_change = False
    for row in trace:
        if 'cmd_ack' not in row.get('outputs', {}):
            return (None, row.get('edge'), 'cmd_ack is not present as a declared observable')
        held = row.get('held', 0)
        if not isinstance(held, int) or held < 1:
            return (False, row.get('edge'), 'cmd_ack has an invalid non-positive held interval')
        value = row['outputs']['cmd_ack']
        if value not in (0, 1):
            return (False, row.get('edge'), f'cmd_ack has invalid value {value}')
        if previous is not None and value != previous:
            observed_change = True
        previous = value

    if not observed_change:
        return (None, None, 'cmd_ack did not change in the sampled trace; no synchronous update was observable')
    return (True, None, 'all observed cmd_ack changes occur between distinct states sampled on rising edges, and remain stable for each held state')

def decide(trace):
    reset_rows = [
        r for r in trace
        if r['inputs'].get('nReset') == 0
    ]
    if not reset_rows:
        return (None, None, 'nReset was never asserted low; reset activation was not exercised')

    bad = [
        r for r in reset_rows
        if r['outputs'].get('cmd_ack') != 0
    ]
    if bad:
        r = bad[0]
        return (False, r['edge'],
                'cmd_ack was not cleared low while nReset was asserted low')

    nonreset_high = [
        r for r in trace
        if r['inputs'].get('nReset') == 1
        and r['outputs'].get('cmd_ack') == 1
    ]
    if not nonreset_high:
        return (None, reset_rows[0]['edge'],
                'reset showed cmd_ack low, but no non-reset cmd_ack-high state was observed to distinguish the reset signature')

    return (True, reset_rows[0]['edge'],
            'cmd_ack was low throughout the observed nReset-low reset state')

def decide(trace):
    if not trace:
        return (None, None, 'the activation never occurred')

    low_seen = any(r['inputs'].get('ena') == 0 for r in trace)
    if not low_seen:
        return (None, None, 'ena was never low; the required scenario was not exercised')

    # A new cmd_ack pulse must not begin while ena is low.
    for i, row in enumerate(trace):
        if row['inputs'].get('ena') != 0:
            continue
        prev_ack = trace[i - 1]['outputs'].get('cmd_ack', 0) if i else 0
        if prev_ack == 0 and row['outputs'].get('cmd_ack', 0) == 1:
            return (False, row['edge'], 'cmd_ack pulsed while ena was low; completion was not postponed')

    # Find a witnessed contrasting completion with ena high: cmd_ack must be
    # a one-clock pulse.  Combine adjacent rows carrying the same output level
    # because input changes can split a state-compressed output run.
    contrasting_pulse = None
    bad_contrast = None
    i = 0
    while i < len(trace):
        row = trace[i]
        if row['outputs'].get('cmd_ack', 0) != 1:
            i += 1
            continue

        prev_ack = trace[i - 1]['outputs'].get('cmd_ack', 0) if i else 0
        if prev_ack == 1 or i == 0:
            i += 1
            continue

        start = row
        total_edges = 0
        j = i
        while j < len(trace) and trace[j]['outputs'].get('cmd_ack', 0) == 1:
            total_edges += trace[j].get('held', 1)
            j += 1

        if start['inputs'].get('ena') == 1:
            if total_edges == 1:
                contrasting_pulse = start
            else:
                bad_contrast = (start, total_edges)
        i = j

    if bad_contrast is not None:
        row, duration = bad_contrast
        return (False, row['edge'], f'contrasting cmd_ack pulse lasted {duration} edges, expected one clock')
    if contrasting_pulse is None:
        return (None, None, 'ena was low, but no corresponding ena-high one-clock cmd_ack completion was observed')

    return (True, contrasting_pulse['edge'], 'cmd_ack was suppressed while ena was low and a one-clock completion pulse was observed with ena high')

def decide(trace):
    # No encoding table is declared for cmd, so its value is treated as an
    # opaque command token rather than compared with an invented integer.
    if not trace:
        return (None, None, 'the command activation never occurred')

    activations = []
    for i, row in enumerate(trace):
        cmd = row['inputs'].get('cmd')
        if cmd is None:
            continue
        if i == 0 or trace[i - 1]['inputs'].get('cmd') != cmd:
            activations.append(i)

    if not activations:
        return (None, None, 'the command activation never occurred')

    failures = []
    saw_signature = False
    for start in activations:
        end = len(trace)
        for j in range(start + 1, len(trace)):
            if trace[j]['outputs'].get('busy') == 1:
                end = j
                break

        signature = None
        last = end if end < len(trace) else len(trace) - 1
        for j in range(start + 1, last + 1):
            previous = trace[j - 1]['outputs'].get('sda_oen')
            current = trace[j]['outputs'].get('sda_oen')
            if (previous != 0 and current == 0
                    and trace[j]['outputs'].get('scl_oen') == 1):
                signature = trace[j]
                break

        if signature is not None:
            saw_signature = True
        elif end < len(trace):
            failures.append((False, trace[start]['edge'],
                             'the command activation was observed, but sda_oen did not become 0 while scl_oen was 1'))

    if failures:
        return failures[0]
    if saw_signature:
        return (True, None,
                'the opaque command activation produced the START signature: sda_oen became 0 while scl_oen was 1')
    return (None, None,
            'the command activation was observed, but the trace ended before a routed START signature was established')

def decide(trace):
    unsupported = {0, 3, 5, 6, 7, 9, 10, 11, 12, 13, 14, 15}

    # The normalized activation identifies the unsupported/idle command
    # alternatives.  busy==0 qualifies the input with the declared output
    # signature of the FSM being idle, rather than treating a held command
    # input during another transaction as a new idle-command activation.
    activations = []
    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        if inputs.get('cmd') not in unsupported or outputs.get('busy') != 0:
            continue
        previous = trace[i - 1] if i else None
        if (previous is None
                or previous.get('inputs', {}).get('cmd') not in unsupported
                or previous.get('outputs', {}).get('busy') != 0):
            activations.append(i)

    if not activations:
        return (None, None, 'no unsupported or idle command was observed while the FSM was idle')

    for i in activations:
        for row in trace[i:]:
            if row.get('outputs', {}).get('cmd_ack') == 1:
                return (False, row.get('edge'),
                        'cmd_ack asserted for an unsupported or idle command; the FSM did not remain idle')

    return (True, trace[activations[0]].get('edge'),
            'cmd_ack remained low for the observed unsupported or idle command while busy was low')

def decide(trace):
    # Route condition: the command sequence has released SCL, while the
    # externally observed SCL input is still low because of stretching.
    stretch = [
        r for r in trace
        if r['outputs'].get('scl_oen') == 1
        and r['inputs'].get('scl_i') == 0
    ]
    if not stretch:
        return (None, None, 'no released-SCL/low-scl_i clock-stretching situation was observed')

    first_low = stretch[0]['index']
    first_high_input = None
    for r in trace:
        if r['index'] > first_low and r['inputs'].get('scl_i') == 1:
            first_high_input = r['index']
            break

    # A newly asserted acknowledgement while the bus is still stretched is
    # the forbidden side of the route signature.
    for i, r in enumerate(trace):
        if r['index'] < first_low:
            continue
        if (r['inputs'].get('scl_i') == 0
                and r['outputs'].get('scl_oen') == 1
                and r['outputs'].get('cmd_ack') == 1):
            previous_ack = (trace[i - 1]['outputs'].get('cmd_ack')
                            if i > 0 else 0)
            if previous_ack != 1:
                return (
                    False,
                    r['edge'],
                    'cmd_ack pulsed while scl_oen was released but scl_i was still low; the routed clock-stretching behaviour requires acknowledgement to wait for scl_i release'
                )

    if first_high_input is None:
        return (
            None,
            None,
            'clock stretching was observed with scl_i low, but scl_i was not later released in the trace'
        )

    released_ack = [
        r for r in trace
        if r['index'] >= first_high_input
        and r['outputs'].get('cmd_ack') == 1
    ]
    if not released_ack:
        return (
            None,
            None,
            'clock stretching was observed and scl_i was released, but no post-release cmd_ack was observed to establish the routed effect'
        )

    return (
        True,
        released_ack[0]['edge'],
        'cmd_ack remained unasserted while released SCL was stretched low and was observed after scl_i became high'
    )

def decide(trace):
    busy_changes = []
    sda_changes = []

    for i, row in enumerate(trace):
        if i > 0:
            prev = trace[i - 1]
            busy_prev = prev["outputs"].get("busy")
            busy_now = row["outputs"].get("busy")
            sda_prev = prev["inputs"].get("sda_i")
            sda_now = row["inputs"].get("sda_i")

            if busy_prev != busy_now:
                busy_changes.append((i, row["edge"], busy_prev, busy_now))
            if sda_prev != sda_now:
                sda_changes.append((i, sda_prev, sda_now))

    if not busy_changes:
        return (None, None, "no START/STOP busy transition occurred in this trace")

    for busy_i, busy_edge, busy_prev, busy_now in busy_changes:
        expected_sda = (1, 0) if busy_now == 1 else (0, 1)
        caused = any(
            sda_i < busy_i and sda_prev == expected_sda[0] and sda_now == expected_sda[1]
            for sda_i, sda_prev, sda_now in sda_changes
        )
        if not caused:
            direction = "assertion" if busy_now == 1 else "deassertion"
            transition = "fall" if busy_now == 1 else "rise"
            return (
                False,
                busy_edge,
                f"busy {direction} was not preceded by an sda_i {transition}; "
                "the specified sda_i-derived START/STOP evidence is absent"
            )

    return (
        True,
        busy_changes[-1][1],
        "each observed busy START/STOP transition was preceded by the corresponding sda_i transition; no exact latency was imposed"
    )

def decide(trace):
    starts = []
    for i, row in enumerate(trace):
        if row.get('outputs', {}).get('cmd_ack') != 1:
            continue
        if i > 0 and trace[i - 1].get('outputs', {}).get('cmd_ack') != 1:
            starts.append(i)

    if not starts:
        return (None, None, 'no cmd_ack completion transition was observed')

    for start in starts:
        total_edges = 0
        j = start
        released = False
        while j < len(trace):
            value = trace[j].get('outputs', {}).get('cmd_ack')
            if value != 1:
                released = True
                break
            total_edges += trace[j].get('held', 0)
            j += 1

        if not released:
            return (None, trace[start].get('edge'),
                    'cmd_ack became asserted, but the trace ended before the acknowledge pulse was released')

        if total_edges != 1:
            return (False, trace[start].get('edge'),
                    f"cmd_ack was asserted for {total_edges} clock edges; the requirement says 'exactly one clock cycle'")

    return (True, trace[starts[-1]].get('edge'),
            "each observed command-complete acknowledge was asserted for exactly one clock cycle")

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout, worst

    def holds(cond):
        def predicate(row):
            return all(
                row['outputs'].get(port, row['inputs'].get(port)) == value
                for port, value in cond.items()
            )
        return predicate

    start_falls = edges(trace, 'sda_i', 'fall')
    stop_rises = edges(trace, 'sda_i', 'rise')

    def start(row):
        return row['inputs'].get('scl_i') == 1 and row['edge'] in start_falls

    def stop(row):
        return row['inputs'].get('scl_i') == 1 and row['edge'] in stop_rises

    def aborted(row):
        return (row['inputs'].get('nReset') == 0 or
                row['inputs'].get('rst') == 1)

    starts = after(trace, start, until=stop, aborts=aborted)

    set_checks = [
        eventually(
            window,
            lambda row: row['outputs'].get('busy') == 1,
            after_activation=True,
            strong=False,
        )
        for window in starts
    ]
    held_checks = [
        throughout(
            window,
            lambda row: row['outputs'].get('busy') == 1,
            after_activation=True,
        )
        for window in starts
    ]

    stop_edges = set()
    for window in starts:
        for row in window.rows:
            if stop(row):
                stop_edges.add(row['edge'])

    stop_windows = after(
        trace,
        lambda row: row['edge'] in stop_edges and stop(row),
        until=TO_END,
        aborts=aborted,
    )
    clear_checks = [
        eventually(
            window,
            lambda row: row['outputs'].get('busy') == 0,
            after_activation=True,
            strong=False,
        )
        for window in stop_windows
    ]

    return worst(set_checks + held_checks + clear_checks)

from specflow.refmodel.temporal import TO_END, after, eventually, edges, worst


def decide(trace):
    # The command encoding is unspecified, so use the supplied port-level
    # signature of arbitration checking rather than a numeric cmd value.
    scl_release_edges = edges(trace, "scl_oen", "rise")

    def arbitration_condition(row):
        return (
            row["edge"] in scl_release_edges
            and row["outputs"].get("scl_oen") == 1
            and row["outputs"].get("sda_oen") == 1
            and row["inputs"].get("sda_i") == 0
            and row["inputs"].get("nReset") != 0
            and row["inputs"].get("rst") != 1
        )

    def acknowledged(row):
        return row["outputs"].get("cmd_ack") == 1

    def aborted(row):
        return (
            row["inputs"].get("nReset") == 0
            or row["inputs"].get("rst") == 1
        )

    windows = after(
        trace,
        arbitration_condition,
        until=acknowledged,
        aborts=aborted,
    )

    return worst([
        eventually(
            window,
            lambda row: row["outputs"].get("al") == 1,
            after_activation=True,
            strong=True,
        )
        for window in windows
    ])

def decide(trace):
    activated = [r for r in trace if r['outputs'].get('sda_oen') == 1]
    if not activated:
        return (None, None, 'sda_oen never sampled at 1; the release condition was not exercised')
    bad = [r for r in activated if r['outputs'].get('sda_oen') != 1]
    if bad:
        return (False, bad[0]['edge'], 'sda_oen was not 1 in a release-condition state')
    return (True, activated[0]['edge'], 'sda_oen is 1, which denotes released SDA')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, throughout, worst

    windows = after(trace, lambda r: True, until=TO_END)

    def outputs_are_not_driven_high(row):
        outputs = row['outputs']
        return outputs.get('scl_o') == 0 and outputs.get('sda_o') == 0

    return worst([
        throughout(w, outputs_are_not_driven_high, after_activation=False)
        for w in windows
    ])

def decide(trace):
    if not trace:
        return (None, None, 'no output-enable level was observed in the trace')

    saw_scl = False
    saw_sda = False

    for row in trace:
        outputs = row['outputs']
        scl_oen = outputs['scl_oen']
        sda_oen = outputs['sda_oen']

        if scl_oen in (0, 1):
            saw_scl = True
        if sda_oen in (0, 1):
            saw_sda = True

        if scl_oen == 0 and outputs['scl_o'] != 0:
            return (False, row['edge'],
                    f'scl_o is {outputs["scl_o"]} while scl_oen is 0; '
                    'the SCL line must be driven low when its output enable is asserted low')

        if sda_oen == 0 and outputs['sda_o'] != 0:
            return (False, row['edge'],
                    f'sda_o is {outputs["sda_o"]} while sda_oen is 0; '
                    'the SDA line must be driven low when its output enable is asserted low')

    if not saw_scl and not saw_sda:
        return (None, None, 'no asserted-low or released-high output-enable level was observed')

    return (True, None,
            'each asserted-low output-enable state drives its corresponding line output low; '
            'high output-enable states release the lines without imposing an unstated drive-data value')

def decide(trace):
    # The internal cnt/clk_en signals are unavailable.  Use the licensed
    # cmd_ack route signature, without assigning numeric meanings to cmd.
    candidates = []
    for i in range(1, len(trace)):
        row = trace[i]
        prev = trace[i - 1]
        ins = row.get('inputs', {})
        prev_ins = prev.get('inputs', {})
        if (ins.get('nReset') == 1 and ins.get('rst') == 0
                and ins.get('ena') == 1
                and ins.get('cmd') != prev_ins.get('cmd')):
            candidates.append(i)

    ack_rises = []
    for i in range(1, len(trace)):
        before = trace[i - 1].get('outputs', {}).get('cmd_ack')
        now = trace[i].get('outputs', {}).get('cmd_ack')
        if before != 1 and now == 1:
            ack_rises.append(i)

    observations = []
    for i in candidates:
        following = [j for j in ack_rises if j > i]
        if not following:
            continue
        j = following[0]
        if any(i < k < j for k in candidates):
            continue
        clk_cnt = trace[i].get('inputs', {}).get('clk_cnt')
        cmd_signature = trace[i].get('inputs', {}).get('cmd')
        if clk_cnt is None:
            continue
        latency = sum(r.get('held', 1) for r in trace[i:j])
        observations.append((cmd_signature, clk_cnt, latency, trace[j].get('edge')))

    comparisons = []
    for a in range(len(observations)):
        for b in range(a + 1, len(observations)):
            cmd_a, cnt_a, lat_a, edge_a = observations[a]
            cmd_b, cnt_b, lat_b, edge_b = observations[b]
            if cmd_a == cmd_b and cnt_a != cnt_b:
                comparisons.append((cnt_a, lat_a, edge_a, cnt_b, lat_b, edge_b))

    if not comparisons:
        return (None, None,
                'no comparable command completions with different clk_cnt values; '
                'the clk_cnt-dependent cmd_ack signature was not exercised')

    for cnt_a, lat_a, edge_a, cnt_b, lat_b, edge_b in comparisons:
        if cnt_a < cnt_b and lat_a >= lat_b:
            return (False, edge_b,
                    f'for the same command signature, clk_cnt {cnt_b} completed in '
                    f'{lat_b} edges no later than clk_cnt {cnt_a} in {lat_a} edges; '
                    'completion timing was not consistently determined by clk_cnt')
        if cnt_b < cnt_a and lat_b >= lat_a:
            return (False, edge_a,
                    f'for the same command signature, clk_cnt {cnt_a} completed in '
                    f'{lat_a} edges no later than clk_cnt {cnt_b} in {lat_b} edges; '
                    'completion timing was not consistently determined by clk_cnt')

    return (True, None,
            'comparable command completions showed cmd_ack latency increasing '
            'consistently with clk_cnt, without asserting an unstated exact count')

def decide(trace):
    def reset_inactive(row):
        return (row['inputs'].get('nReset') == 1 and
                row['inputs'].get('rst') == 0)

    def disabled(row):
        return reset_inactive(row) and row['inputs'].get('ena') == 0

    # Identify rising acknowledgement transitions without assuming a
    # particular number of states or clock edges after the condition.
    ack_rises = []
    previous = None
    for i, row in enumerate(trace):
        ack = row['outputs'].get('cmd_ack')
        if i > 0 and ack == 1 and previous != 1:
            ack_rises.append((i, row['edge']))
        previous = ack

    # Delimit each contiguous ena-low interval while reset is inactive.
    # These indices describe the observed condition; they are not a latency
