        prev = trace[i - 1]["outputs"].get("scl_oen")
        row = trace[i]
        oen = row["outputs"].get("scl_oen")
        scl_i = row["inputs"].get("scl_i")
        if prev != 1 and oen == 1 and scl_i == 0:
            activations.append(i)

    if not activations:
        return (None, None, "no scl_oen release while scl_i was low; stretch situation was not exercised")

    saw_holding = False
    saw_nonholding = False

    for start in activations:
        for j in range(start + 1, len(trace)):
            row = trace[j]
            oen = row["outputs"].get("scl_oen")
            scl_i = row["inputs"].get("scl_i")
            prev_oen = trace[j - 1]["outputs"].get("scl_oen")

            # Falling while the externally observed SCL is still low is the
            # route's otherwise case and violates the required indication.
            if prev_oen == 1 and oen == 0 and scl_i == 0:
                saw_nonholding = True
                return (False, row["edge"],
                        "scl_oen transitioned low while scl_i remained low; "
                        "the held-low SCL was not indicated by keeping SCL released")

            # The input has been released while the output-enable is still
            # high: this is evidence of the required held-high stretch case.
            if scl_i == 1 and oen == 1:
                saw_holding = True
                break

    if not saw_holding:
        return (None, None,
                "scl_oen was released while scl_i was low, but the trace ended "
                "before showing either SCL release or a completed stretch")

    if not saw_nonholding:
        return (None, None,
                "scl_oen remained high while scl_i was low, but the trace showed "
                "only the holding case and no contrasting route behavior")

    return (True, None,
            "scl_oen remained high until scl_i was released high for the observed stretch case")

