def decide(trace):
    # The activation is the declared-port signature of slave_wait:
    # scl_oen must RISE while the filtered SCL input is still low.
    scl_oen_rises = edges(trace, 'scl_oen', 'rise')
    scl_i_rises = edges(trace, 'scl_i', 'rise')

    def slave_wait_opens(row):
        return (row['edge'] in scl_oen_rises
                and row['inputs'].get('scl_i') == 0)

    def scl_released(row):
        return row['edge'] in scl_i_rises

    windows = after(trace, slave_wait_opens, until=scl_released)
    if not windows:
        return (None, None,
                'slave-wait activation never occurred: scl_oen did not rise while scl_i was low')

    results = []
    missing_release = []
    missing_completion = []

    for w in windows:
        held = throughout(
            w,
            lambda r: r['outputs'].get('cmd_ack') == 0,
            after_activation=False,
        )
        results.append(held)

        if not w.closed:
            missing_release.append(w.edge)
            continue

        release_rows = [
            r for r in trace
            if r['edge'] > w.edge and scl_released(r)
        ]
        if not release_rows:
            missing_release.append(w.edge)
            continue

        release_edge = release_rows[0]['edge']
        post_release = after(
            trace,
            lambda r, e=release_edge: r['edge'] == e,
            until=TO_END,
        )
        completion = [
            eventually(pw, lambda r: r['outputs'].get('cmd_ack') == 1,
                       after_activation=False, strong=False)
            for pw in post_release
        ]
        if completion:
            results.extend(completion)
        else:
            missing_completion.append(release_edge)

    verdict = worst(results)
    if verdict[0] is False:
        return verdict
    if missing_release:
        return (None, missing_release[0],
                'slave-wait opened, but SCL release was not observed before the trace ended')
    if missing_completion:
        return (None, missing_completion[0],
                'SCL was released, but the postponed cmd_ack completion was not observed in the trace')
    return (True, None,
            'cmd_ack remained low while SCL was held low and completion was observed only after SCL release')

