                break
        if synchronized_ack is not None:
            break

    if synchronized_ack is None:
        return (False, trace[sync_events[0]]['edge'],
                'cmd_ack did not occur after the shared-bus SCL-low synchronization signature')

    first_sync = sync_events[0]
    normal_ack = None
    for i, row in enumerate(trace):
        if i < first_sync and row['outputs'].get('cmd_ack') == 1:
            normal_ack = row
            break

    if normal_ack is None:
        return (None, synchronized_ack['edge'],
                'synchronized cmd_ack was observed, but no normal completion case was present to establish the routed difference')

