        busy_after = next(
            (r for r in later if r["edge"] in busy_rises), None)
        sda_back = next(
            (r for r in later if r["edge"] in sda_rises), None)

        if busy_after is not None and (
                sda_back is None or busy_after["index"] < sda_back["index"]):
            positive = True
        elif sda_back is not None and sda_back["outputs"].get("busy") == 0:
            negative = True
        else:
            bad = row

    if bad is not None:
        return (False, bad["edge"],
                "the SDA filter response did not show either licensed busy-rise or glitch-rejection behavior")
    if not positive or not negative:
        return (None, None,
                "the trace exercised only one side of the busy route; both persistent-sample and narrow-glitch signatures are needed")
    return (True, None,
            "busy rose after a persistent SDA fall and remained low for a narrower SDA glitch")

def decide(trace):
    candidates = []
    i = 1
    while i < len(trace):
        prev = trace[i - 1]
        row = trace[i]
        prev_sda = prev['inputs'].get('sda_i')
        sda = row['inputs'].get('sda_i')
        scl = row['inputs'].get('scl_i')

        # A low pulse must be entered by a high-to-low transition while SCL
        # is high; input values are used only to qualify the stimulus.
        if prev_sda == 1 and sda == 0 and scl == 1:
            j = i
            duration = 0
            valid = True
            while j < len(trace) and trace[j]['inputs'].get('sda_i') == 0:
                if trace[j]['inputs'].get('scl_i') != 1:
                    valid = False
                    break
                duration += trace[j].get('held', 1)
                j += 1

            # The three-sample acceptance interval qualifies the trigger;
            # it does not impose a response timing requirement.
            if valid and j < len(trace) and trace[j]['inputs'].get('sda_i') == 1 and duration < 3:
                candidates.append((i, j))
            i = max(i + 1, j)
        else:
            i += 1

    if not candidates:
        return (None, None, 'no short sda_i glitch matching the three-sample acceptance qualification occurred')

    unknown = None
    for start, end in candidates:
        check_end = end + 1
        if check_end >= len(trace):
            if unknown is None:
                unknown = trace[start]['edge']
            continue

        for k in range(start, check_end + 1):
            busy = trace[k]['outputs'].get('busy')
            if busy != 0:
                return (False, trace[k]['edge'], 'busy asserted during or immediately after a short sda_i low glitch; expected no START-detection response')

    if unknown is not None:
        return (None, unknown, 'short sda_i glitch occurred, but the immediately-after state was not present in the trace')

    return (True, None, 'busy remained low during and immediately after each short sda_i low glitch')

def decide(trace):
    def busy_rise(i):
        if i < 0 or trace[i]['outputs'].get('busy') != 1:
            return False
        if i == 0:
            return False
        return trace[i - 1]['outputs'].get('busy') == 0

    positive = []
    other = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if row['outputs'].get('busy') != 0:
            continue
        old_sda = prev['inputs'].get('sda_i')
        new_sda = row['inputs'].get('sda_i')
        scl_high = row['inputs'].get('scl_i') == 1
        changed = old_sda != new_sda
        if old_sda == 1 and new_sda == 0 and scl_high:
            positive.append(i)
        elif changed:
            other.append(i)

    if not positive and not other:
        return (None, None, 'no declared-port SDA transition while busy was idle')

    for i in positive:
        rise = next((j for j in range(i, len(trace)) if busy_rise(j)), None)
        if rise is None:
            return (False, trace[i]['edge'], 'filtered SDA-fall/SCL-high START signature was observed, but busy never rose')

    other_checked = False
    for i in other:
        next_positive = next((p for p in positive if p > i), len(trace))
        false_rise = next((j for j in range(i, next_positive) if busy_rise(j)), None)
        if false_rise is not None:
            return (False, trace[false_rise]['edge'], 'busy rose for an SDA transition that was not a falling edge while SCL was high')
        other_checked = True

    if not positive or not other_checked:
        return (None, None, 'only one side of the START-condition observation was exercised')

    return (True, trace[positive[0]]['edge'], 'busy rose for each START signature and did not rise for non-START SDA transitions')

