            results.append((None, trace[start].get('edge'), 'no busy response observed after the raw sda_i transition'))
            continue

        j, elapsed = response
        if elapsed < 2:
            results.append((False, trace[j].get('edge'), f'busy changed {elapsed} rising-clock edge(s) after the raw sda_i transition; the two-stage capture requires at least 2'))
        else:
            results.append((True, trace[j].get('edge'), f'busy changed after {elapsed} rising-clock edge(s), allowing the two-stage capture and unspecified subsequent processing latency'))

    for result in results:
        if result[0] is False:
            return result
    for result in results:
        if result[0] is None:
            return result
    return (True, results[-1][1], 'all observed raw sda_i transitions were followed by busy changes only after at least two capture-stage edges')

def decide(trace):
    episodes = []
    i = 1
    while i < len(trace):
        prev = trace[i - 1]
        row = trace[i]
        falling_start = (
            prev['inputs'].get('scl_i') == 1 and
            row['inputs'].get('scl_i') == 1 and
            prev['inputs'].get('sda_i') == 1 and
            row['inputs'].get('sda_i') == 0
        )
        if not falling_start:
            i += 1
            continue

        j = i
        duration = 0
        while j < len(trace):
            current = trace[j]
            if (current['inputs'].get('scl_i') != 1 or
                    current['inputs'].get('sda_i') != 0):
                break
            duration += current['held']
            j += 1

        episodes.append({
            'start': i,
            'end': j,
            'duration': duration,
        })
        i = j

    if len(episodes) < 2:
        return (None, None,
                'short and sustained SDA-low disturbances were not both exercised')

    short = min(episodes, key=lambda e: e['duration'])
    sustained = max(episodes, key=lambda e: e['duration'])
    if short['duration'] >= sustained['duration']:
        return (None, None,
                'no distinguishable short and sustained disturbance durations were observed')

    for k in range(short['start'], short['end']):
        if trace[k]['outputs'].get('busy') != 0:
            return (False, trace[k]['edge'],
                    'busy rose for the shorter SDA-low disturbance; the route says filtering must keep busy low')

    rise_edge = None
    for k in range(sustained['start'], len(trace)):
        if trace[k]['outputs'].get('busy') != 1:
            continue
        before = trace[k - 1]['outputs'].get('busy') if k > 0 else None
        if before == 0:
            rise_edge = trace[k]['edge']
            break

    if rise_edge is None:
        return (False, trace[sustained['start']]['edge'],
                'busy did not rise for the longer sustained SDA falling transition; no response latency is specified')

    return (True, rise_edge,
            'busy stayed low for the shorter disturbance and rose after the longer sustained SDA falling transition')

def decide(trace):
    responded = []
    rejected = []

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        old_sda = prev['inputs'].get('sda_i')
        new_sda = row['inputs'].get('sda_i')
        if old_sda == new_sda or row['inputs'].get('scl_i') != 1:
            continue

        fall = old_sda == 1 and new_sda == 0
        rise = old_sda == 0 and new_sda == 1
        busy = row['outputs'].get('busy')
        if fall and busy != 0:
            continue
        if rise and busy != 1:
            continue

        expected_busy = 1 if fall else 0
        found_response = False
        before_next_sda_change = True
        for j in range(i + 1, len(trace)):
            later = trace[j]
            if j > i + 1 and later['inputs'].get('sda_i') != trace[j - 1]['inputs'].get('sda_i'):
                before_next_sda_change = False
                break
            if later['outputs'].get('busy') == expected_busy:
                found_response = True
                break

        if found_response:
            responded.append((row['edge'], 'START' if fall else 'STOP'))
        elif not before_next_sda_change:
            rejected.append((row['edge'], 'glitch'))

    if not responded and not rejected:
        return (None, None, 'no qualifying majority-filter signature occurred in this trace')
    if not responded:
        return (None, rejected[0][0], 'only non-responding SDA transitions were observed; no filtered response was exercised')
    if not rejected:
        return (None, responded[0][0], 'only responding SDA transitions were observed; no single-sample rejection was exercised')

    return (True, None, f'majority-filter signature observed: {len(responded)} responding transition(s) and {len(rejected)} rejected glitch transition(s)')

def decide(trace):
    def rises(port):
        result = []
        for i in range(1, len(trace)):
            before = trace[i - 1].get('inputs', {}).get(port)
            now = trace[i].get('inputs', {}).get(port)
            if before == 0 and now == 1:
                result.append(i)
        return result

    scl_rises = rises('scl_i')
    if not scl_rises:
        return (None, None, 'no rising scl_i sampling signature occurred; the filtered-SCL situation was not exercised')

    # Each rising-SCL sampling situation must eventually be represented at dout.
    # No fixed edge count is assumed; effect_follows is false, so the trigger
    # row is also a valid observation row.
    for i in scl_rises:
        sampled_sda = trace[i].get('inputs', {}).get('sda_i')
        found = False
        for row in trace[i:]:
            if row.get('outputs', {}).get('dout') == sampled_sda:
                found = True
                break
        if not found:
            if trace[-1].get('index') == trace[i].get('index'):
                return (None, trace[i].get('edge'), 'the sampling window is incomplete at the end of the trace')
            return (False, trace[i].get('edge'), 'dout did not reach the stable filtered SDA value after a rising filtered-SCL signature')

    # The routed observation must not show a new capture in the absence of a
    # sampling trigger. A dout transition is licensed only after a prior rise.
    for i in range(1, len(trace)):
        old = trace[i - 1].get('outputs', {}).get('dout')
        new = trace[i].get('outputs', {}).get('dout')
        if old != new and not any(rise < i for rise in scl_rises):
            return (False, trace[i].get('edge'), 'dout changed without a preceding rising filtered-SCL sampling signature')

    return (True, None, 'dout reflects the stable sampled SDA value for each rising filtered-SCL signature and does not change without such a trigger')

def decide(trace):
    # The internal dSCL/dSDA signals are not declared ports.  Use the licensed
    # busy route as a signature of the filtered-bus situation instead.
    events = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        old_sda = prev['inputs'].get('sda_i')
        new_sda = row['inputs'].get('sda_i')
        if old_sda == new_sda:
            continue
        # The raw declared bus inputs are the available signature of a
        # filtered SDA transition; no filter latency is assumed.
        scl_high = row['inputs'].get('scl_i') == 1
        events.append((i, scl_high, new_sda < old_sda))

    if not events:
        return (None, None, 'no SDA transition was observed; the routed filtered-bus situation did not occur')

    high_cases = []
    low_cases = []
    for n, (i, scl_high, falling) in enumerate(events):
        end = events[n + 1][0] if n + 1 < len(events) else len(trace)
        if scl_high:
            # Falling SDA while SCL is high is START; rising SDA is STOP.
            expected = 1 if falling else 0
            high_cases.append((i, end, expected))
        else:
            low_cases.append((i, end))

    if not high_cases or not low_cases:
        return (None, trace[events[0][0]]['edge'],
                'only one side of the routed busy signature was observed')

    # A transition at the start of the interval is permitted: the
    # specification does not state whether filtering and observation are
    # represented in the same distinct state or a later one.
    for start, end, expected in high_cases:
        seen = any(
            trace[j]['outputs'].get('busy') == expected
            for j in range(start, end)
        )
        if not seen:
            return (False, trace[start]['edge'],
                    f'busy did not reach {expected} for the START/STOP signature before the next SDA transition')

    for start, end in low_cases:
        if end == len(trace):
            return (None, trace[start]['edge'],
                    'the low-SCL routed case was observed, but the trace ended before its unchanged interval was bounded')
        initial = trace[start]['outputs'].get('busy')
        changed = any(
            trace[j]['outputs'].get('busy') != initial
            for j in range(start, end)
        )
        if changed:
            return (False, trace[start]['edge'],
                    'busy changed for an SDA transition while the filtered SCL signature was low')

    return (True, None,
            'both routed cases were observed: high-SCL SDA transitions reached the corresponding busy state and low-SCL transitions left busy unchanged')

from specflow.refmodel.temporal import TO_END, after, eventually, stable, edges, worst

def decide(trace):
    def row_has(row, port, value):
        return row['inputs'].get(port) == value

    sda_falls = edges(trace, 'sda_i', 'fall')
    sda_rises = edges(trace, 'sda_i', 'rise')
    busy_rises = edges(trace, 'busy', 'rise')
    busy_falls = edges(trace, 'busy', 'fall')

    starts = after(
        trace,
        lambda r: r['edge'] in sda_falls and row_has(r, 'scl_i', 1),
        until=TO_END,
    )
    stops = after(
        trace,
        lambda r: r['edge'] in sda_rises and row_has(r, 'scl_i', 1),
        until=TO_END,
    )

    def next_high_sda_event(row):
        return (
            row['edge'] in sda_falls or row['edge'] in sda_rises
        ) and row_has(row, 'scl_i', 1)

    low_sda_events = after(
        trace,
        lambda r: (
            (r['edge'] in sda_falls or r['edge'] in sda_rises)
            and row_has(r, 'scl_i', 0)
        ),
        until=next_high_sda_event,
    )

    checks = []
    checks.extend(
        eventually(
            w,
            lambda r: r['edge'] in busy_rises,
            after_activation=False,
            strong=True,
        )
        for w in starts
    )
    checks.extend(
        eventually(
            w,
            lambda r: r['edge'] in busy_falls,
            after_activation=False,
            strong=True,
        )
        for w in stops
    )
    checks.extend(stable(w, 'busy') for w in low_sda_events)

    result = worst(checks)
    if result[0] is False:
        return (False, result[1], result[2])
    if checks:
        return result
    return (None, None, 'no declared bus transition exercised this comparison scenario')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, edges, worst

    rises = edges(trace, "sda_i", "rise")

    def stop_activation(row):
        return (row["edge"] in rises
                and row["inputs"].get("scl_i") == 1
                and row["outputs"].get("busy") == 1)

    def closes_on_scl_low(row):
        return row["inputs"].get("scl_i") == 0

    stop_windows = after(trace, stop_activation, until=closes_on_scl_low)
    stop_verdicts = [
        eventually(
            window,
            lambda row: row["outputs"].get("busy") == 0,
            after_activation=True,
            strong=True,
        )
        for window in stop_windows
    ]

    # Check the alternative route case: while busy is high and SCL is high,
    # if SDA does not rise, busy must remain high.  Group consecutive distinct
    # states having SCL high and no SDA rising transition.
    quiet_segments = []
    current = []
    for row in trace:
        quiet = (row["inputs"].get("scl_i") == 1
                 and row["edge"] not in rises)
        if quiet:
            current.append(row)
        elif current:
            quiet_segments.append(current)
            current = []
    if current:
        quiet_segments.append(current)

    no_stop_seen = False
    no_stop_failure = None
    no_stop_edge = None
    for segment in quiet_segments:
        busy_positions = [i for i, row in enumerate(segment)
                          if row["outputs"].get("busy") == 1]
        if not busy_positions:
            continue
        no_stop_seen = True
        first_busy = busy_positions[0]
        for row in segment[first_busy:]:
            if row["outputs"].get("busy") != 1:
                no_stop_failure = (False, row["edge"],
                                   "busy did not remain high while SDA did not transition low-to-high with SCL high")
                no_stop_edge = row["edge"]
                break
        if no_stop_failure is not None:
            break

    stop_seen = bool(stop_windows)
    if stop_seen:
        stop_result = worst(stop_verdicts)
        if stop_result[0] is False:
            return stop_result
    else:
        stop_result = (None, None, "no STOP transition was observed")

    if no_stop_failure is not None:
        return no_stop_failure

    if not stop_seen or not no_stop_seen:
        missing = []
        if not stop_seen:
            missing.append("STOP case")
        if not no_stop_seen:
            missing.append("no-STOP case")
        return (None, None, "only one route case was exercised; missing " + " and ".join(missing))

    return (True, None, "busy cleared after the STOP transition and remained high when no STOP transition occurred")

def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, edges, throughout, worst

    def stalled(row):
        return (row['outputs'].get('scl_oen') == 1 and
                row['inputs'].get('scl_i') == 0)

    # This is a level signature, not a command encoding: the controller has
    # released SCL while the observed bus level remains low.
    windows = after(trace, stalled, until=WHILE_ACTIVE)
    if not windows:
        return (None, None, 'the SCL-held-low activation never occurred')

    ack_rises = edges(trace, 'cmd_ack', 'rise')

    # A new completion pulse must not occur while the bus participant is
    # holding SCL low.  The routed observation is about postponement, so an
    # existing level is not treated as a new pulse.
    verdicts = [
        throughout(
            w,
            lambda r: r['edge'] not in ack_rises,
            after_activation=False
        )
        for w in windows
    ]
    bad = [v for v in verdicts if v[0] is False]
    if bad:
        return bad[0]

    # The route describes a difference at cmd_ack.  Without evidence of the
    # ordinary completion side, the trace cannot establish that this was a
    # postponed completion rather than a design that never completes.
    normal_completion = [
        r for r in trace
        if r['edge'] in ack_rises and not stalled(r)
    ]
    if not normal_completion:
        return (None, None,
                'SCL-held-low was observed, but no normal cmd_ack completion was observed for comparison')

    return (True, normal_completion[0]['edge'],
            'cmd_ack was postponed while scl_oen was released and scl_i remained low; normal completion was observed outside that condition')

def decide(trace):
    def active_stall(row):
        return (row['inputs'].get('scl_i') == 0 and
                row['outputs'].get('busy') == 1)

    if not trace:
        return (None, None, 'no trace states; slave-wait activation was not observed')

    # Establish the ordinary completion side of the routed observation before
    # the first observed stall.  This does not assert its width or timing.
    first_stall = None
    for i, row in enumerate(trace):
        if active_stall(row) and (i == 0 or not active_stall(trace[i - 1])):
            first_stall = i
            break

    if first_stall is None:
        return (None, None, 'slave-wait activation was not observed')

    ordinary_completion = any(
        row['outputs'].get('cmd_ack') == 1
        for row in trace[:first_stall]
    )

    i = first_stall
    stalls = 0
    while i < len(trace):
        if not active_stall(trace[i]):
            i += 1
            continue

        start = i
        stalls += 1
        while i < len(trace) and active_stall(trace[i]):
            if trace[i]['outputs'].get('cmd_ack') == 1:
                return (
                    False,
                    trace[i]['edge'],
                    'cmd_ack occurred while SCL was held low during an active command; '
                    'completion was not postponed until the slave-wait condition cleared'
                )
            i += 1

        # The stall ran to the end, so no release and no subsequent completion
        # were observed.
        if i >= len(trace):
            return (
                None,
                trace[start]['edge'],
                'slave-wait activation occurred but SCL was not observed released '
                'before the trace ended'
            )

        completion = None
        for j in range(i, len(trace)):
            if trace[j]['outputs'].get('cmd_ack') == 1:
                completion = j
                break

        if completion is None:
            return (
                None,
                trace[start]['edge'],
                'slave-wait activation occurred and no cmd_ack was observed after '
                'SCL was released'
            )

        i = completion + 1

    if not ordinary_completion:
        return (
            None,
            trace[first_stall]['edge'],
            'the stalled completion was observed, but ordinary cmd_ack behaviour '
            'was not present to establish the routed difference'
        )

    return (
        True,
        trace[first_stall]['edge'],
        f'{stalls} slave-wait stall(s) postponed cmd_ack until SCL was released'
    )

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    scl_changes = edges(trace, "scl_oen", "change")

    def active_write(row):
        return (
            row["outputs"].get("busy") == 1
            and row["inputs"].get("ena") == 1
            and row["inputs"].get("nReset") == 1
            and row["inputs"].get("rst") == 0
            and row["outputs"].get("al") == 0
            and row["inputs"].get("scl_i") == 1
        )

    def complete(row):
        return row["outputs"].get("cmd_ack") == 1

    def aborted(row):
        return (
            row["inputs"].get("nReset") == 0
            or row["inputs"].get("rst") == 1
            or row["outputs"].get("al") == 1
        )

    windows = after(
        trace,
        active_write,
        until=complete,
        aborts=aborted,
    )

    return worst([
        eventually(
            window,
            lambda row: row["edge"] in scl_changes,
            strong=window.closed,
            after_activation=False,
        )
        for window in windows
    ])

def decide(trace):
    activations = []
    for i, row in enumerate(trace):
        if i == 0:
            continue
        prev = trace[i - 1]
        out = row.get('outputs', {})
        prev_out = prev.get('outputs', {})
        inp = row.get('inputs', {})
        if (prev_out.get('busy') != 1 and out.get('busy') == 1
                and inp.get('nReset') == 1
                and inp.get('ena') == 1):
            activations.append(i)

    if not activations:
        return (None, None,
                'no command-sequence activation observed: busy never rose while nReset was released and ena was enabled')

    for start in activations:
        clk_cnt_value = trace[start].get('inputs', {}).get('clk_cnt')
        end = len(trace) - 1
        for j in range(start + 1, len(trace)):
            if trace[j].get('outputs', {}).get('busy') != 1:
                end = j
                break

        ack_rise = None
        for j in range(start + 1, end + 1):
            ack = trace[j].get('outputs', {}).get('cmd_ack')
            prev_ack = trace[j - 1].get('outputs', {}).get('cmd_ack')
            if prev_ack != 1 and ack == 1:
                ack_rise = j
                break

        if ack_rise is not None:
            return (True, trace[ack_rise].get('edge'),
                    f'cmd_ack rose after the command-sequence activation with fixed clk_cnt={clk_cnt_value}')

        if end < len(trace) - 1:
            return (False, trace[end].get('edge'),
                    f'no cmd_ack pulse occurred before command completion for fixed clk_cnt={clk_cnt_value}')

    return (None, None,
            'command activation was observed but the trace ended before its completion acknowledgment')

def decide(trace):
    pulses = []
    active_start = None
    active_edges = 0
    saw_prior_state = False

    for row in trace:
        value = row['outputs'].get('cmd_ack')
        held = row.get('held', 1)

        if value == 1:
            if active_start is None:
                # A pulse already high in the first sampled state has no
                # observable rising edge in this trace.
                if not saw_prior_state:
                    continue
                active_start = row
                active_edges = 0
            active_edges += held
        else:
            if active_start is not None:
                pulses.append((active_start, active_edges))
                active_start = None
                active_edges = 0

        saw_prior_state = True

    if active_start is not None:
        if not pulses:
            return (None, active_start.get('edge'),
                    'cmd_ack route pulse reached the end of the trace before its low state was observed')
        return (None, active_start.get('edge'),
                'a cmd_ack route pulse was incomplete at the end of the trace')

    if not pulses:
        return (None, None, 'cmd_ack did not show the counter-expiration route signature')

    for start, duration in pulses:
        if duration != 1:
            return (False, start.get('edge'),
                    f'cmd_ack was high for {duration} edges; the route requires it to pulse high for exactly one clk cycle')

    return (True, pulses[0][0].get('edge'),
            f'{len(pulses)} counter-expiration route pulse(s) observed; each was high for exactly one clk cycle')

def decide(trace):
    active_transitions = []

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_out = prev.get('outputs', {})
        out = row.get('outputs', {})
        prev_in = prev.get('inputs', {})
        inp = row.get('inputs', {})

        # `busy` is the declared-output signature that a command sequence is active.
        if out.get('busy') != 1:
            continue

        # The FSM's phase advance is observable as an action on scl_oen.
        scl_changed = prev_out.get('scl_oen') != out.get('scl_oen')
        if not scl_changed:
            continue

        # Do not assume a numeric terminal value for clk_cnt.  A change in the
        # declared counter is the available signature of the derived timing tick.
        counter_changed = prev_in.get('clk_cnt') != inp.get('clk_cnt')
        active_transitions.append((row, counter_changed))

    if not active_transitions:
        return (None, None,
                'no active command-sequence scl_oen phase advance was observed; the clk_en-controlled transition was not exercised')

    for row, counter_changed in active_transitions:
        if not counter_changed:
            return (False, row.get('edge'),
                    'scl_oen advanced during an active command sequence without a clk_cnt timing-boundary change, contrary to "only when clk_en is asserted"')

    return (True, active_transitions[0][0].get('edge'),
            'every observed active-sequence scl_oen phase advance coincided with a clk_cnt timing-boundary change, the declared-port signature of the clk_en-controlled advance')

def decide(trace):
    # A command sequence is evidenced at the boundary by cmd_ack completing
    # after ena is reasserted.  No numeric cmd encoding is specified.
    def ack_rise(i):
        if i == 0:
            return bool(trace[i]['outputs'].get('cmd_ack', 0))
        return (not bool(trace[i - 1]['outputs'].get('cmd_ack', 0))
                and bool(trace[i]['outputs'].get('cmd_ack', 0)))

    exercised = []
    i = 0
    while i < len(trace):
        ena_low = trace[i]['inputs'].get('ena') == 0
        previous_low = (i > 0 and trace[i - 1]['inputs'].get('ena') == 0)
        if not ena_low or previous_low:
            i += 1
            continue

        low_start = i
        high = None
        j = i + 1
        while j < len(trace):
            if trace[j]['inputs'].get('ena') != 0:
                high = j
                break
            j += 1

        if high is None:
            i = len(trace)
            continue

        completion = None
        k = high
        while k < len(trace):
            if ack_rise(k):
                completion = k
                break
            k += 1

        if completion is not None:
            early = [r for k, r in enumerate(trace[low_start:high], low_start)
                     if ack_rise(k)]
            exercised.append((low_start, high, early, completion))

        i = high

    if not exercised:
        return (None, None,
                'no disabled command interval was evidenced by cmd_ack completion after ena was reasserted')

    for low_start, high, early, completion in exercised:
        if early:
            return (False, early[0]['edge'],
                    'cmd_ack completed while ena was low; completion was not postponed until ena was reasserted')

    return (True, trace[exercised[-1][3]]['edge'],
            'cmd_ack was absent during each exercised ena-low interval and completed only after ena was reasserted')

def decide(trace):
    def high_phase(row):
        outputs = row['outputs']
        inputs = row['inputs']
        return (outputs.get('scl_oen') == 1 and
                outputs.get('sda_oen') == inputs.get('din'))

    phases = []
    i = 0
    while i < len(trace):
        if not high_phase(trace[i]):
            i += 1
            continue
        start = i
        while i < len(trace) and high_phase(trace[i]):
            i += 1
        phases.append((start, i, i < len(trace)))

    if not phases:
        return (None, None,
                'stable WRITE high-phase signature never occurred')

    saw_low = False
    saw_high = False
    low_missing = None
    high_bad = None

    for start, end, closed in phases:
        rows = trace[start:end]
