def decide(trace):
    ports = ('scl_o', 'scl_oen', 'sda_o', 'sda_oen')

    def signature(row):
        return tuple(row['outputs'].get(p) for p in ports)

    activations = []
    previous = None
    for i, row in enumerate(trace):
        busy = row['outputs'].get('busy') == 1
        cmd = row['inputs'].get('cmd')
        cmd_changed = previous is not None and cmd != previous['inputs'].get('cmd')
        busy_started = (previous is None or previous['outputs'].get('busy') != 1) and busy
        if busy and (busy_started or cmd_changed):
            activations.append(i)
        previous = row

    if not activations:
        return (None, None, 'no command-driven line-control phase was observed')

    for start in activations:
        start_row = trace[start]
        before = signature(trace[start - 1]) if start > 0 else signature(start_row)
        for i in range(start, len(trace)):
            row = trace[i]
            if i > start and row['outputs'].get('busy') != 1:
                break
            if i > start and row['inputs'].get('cmd') != start_row['inputs'].get('cmd'):
                break
            if signature(row) != before:
                return (True, row['edge'], 'SCL/SDA line-control outputs changed during the command-driven control phase')
        end = trace[start]
        for i in range(start + 1, len(trace)):
            if trace[i]['outputs'].get('busy') != 1 or trace[i]['inputs'].get('cmd') != start_row['inputs'].get('cmd'):
