def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, never, worst

    def start_with(value):
        falls = edges(trace, "sda_i", "fall")
        return lambda r: (
            r["edge"] in falls
            and r["inputs"].get("scl_i") == 1
            and r["inputs"].get("ena") == value
        )

    busy_rises = edges(trace, "busy", "rise")
    enabled = after(trace, start_with(1), until=TO_END)
    disabled = after(trace, start_with(0), until=TO_END)

    verdicts = []
    if enabled:
        verdicts.extend(
            eventually(
                w,
                lambda r: r["outputs"].get("busy") == 1,
                strong=True,
                after_activation=True,
            )
            for w in enabled
        )
    if disabled:
        verdicts.extend(
            never(
                w,
                lambda r: r["edge"] in busy_rises,
                after_activation=True,
            )
            for w in disabled
        )

    if not enabled or not disabled:
        missing = []
        if not enabled:
            missing.append("ena=1 START-shaped case")
        if not disabled:
            missing.append("ena=0 START-shaped case")
        if not verdicts:
            return (None, None, "activation never occurred: " + ", ".join(missing))
        result = worst(verdicts)
        if result[0] is False:
            return result
        return (None, result[1], "insufficient paired evidence; missing " + ", ".join(missing))

    return worst(verdicts)

