        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    # The routed situation is a transaction in progress.  busy is used only
    # to recognise that situation; it is not the effect being checked.
    transactions = []
    active = None
    elapsed = 0
    previous_busy = None
    previous_scl = None

