        held = row.get('held', 1)
        busy = out(row, 'busy')
        scl = out(row, 'scl_oen')
        cnt = inp(row, 'clk_cnt')

        if previous_busy is not None and previous_busy == 0 and busy == 1:
            active = {
                'value': cnt,
                'transitions': [],
                'start_edge': row.get('edge')
            }
            elapsed = 0
            previous_scl = scl

        if active is not None:
