            if previous_busy is not None and previous_busy == 1 and busy == 0:
                if len(active['transitions']) >= 2:
                    intervals = []
                    for i in range(1, len(active['transitions'])):
                        intervals.append(
                            active['transitions'][i] - active['transitions'][i - 1]
                        )
                    ordered = sorted(intervals)
                    active['median'] = ordered[len(ordered) // 2]
                    transactions.append(active)
                active = None

        previous_busy = busy
        previous_scl = scl

    if not transactions:
