def decide(trace):
    # `cnt` and `clk_en` are internal.  Use the routed cmd_ack timing
    # signature, qualified by the design's busy state and disabled interval.
    if len(trace) < 2:
        return (None, None, 'no observable command-sequence state was present')

    def reset_inactive(row):
        return (row['inputs'].get('nReset') == 1 and
                row['inputs'].get('rst') == 0)

    def disabled_busy(row):
        return (reset_inactive(row) and
                row['outputs'].get('busy') == 1 and
                row['inputs'].get('ena') == 0)

    def ack_rise(i):
        return (trace[i]['outputs'].get('cmd_ack') == 1 and
                trace[i - 1]['outputs'].get('cmd_ack') != 1)

    starts = []
    for i in range(1, len(trace)):
        if disabled_busy(trace[i]) and not disabled_busy(trace[i - 1]):
            starts.append(i)

    if not starts:
        return (None, None,
                'no busy command sequence entered the disabled interval')

    for start in starts:
        i = start
        while i < len(trace) and disabled_busy(trace[i]):
            if ack_rise(i):
                return (False, trace[i]['edge'],
                        'cmd_ack rose while the command sequence was disabled; '
                        'the routed timing signature requires completion to be delayed '
                        'during the ena-low interval')
            i += 1

        # The interval may run to the end of the trace, so completion is not
        # owed by this observation alone.
        if i >= len(trace):
            continue

        j = i
        while j < len(trace):
            if ack_rise(j):
                return (True, trace[j]['edge'],
                        'cmd_ack rose only after the disabled interval ended; '
                        'no exact clk_cnt latency is assumed')
            if (trace[j]['outputs'].get('busy') != 1 or
                    not reset_inactive(trace[j])):
                break
            j += 1

    return (None, None,
            'the disabled command interval was observed, but no post-interval '
            'cmd_ack completion was present in the trace')

def decide(trace):
    def reset_inactive(row):
        return (row['inputs'].get('nReset') == 1 and
                row['inputs'].get('rst') == 0)

    def disabled(row):
        return reset_inactive(row) and row['inputs'].get('ena') == 0

    # Identify rising acknowledgement transitions without assuming a
    # particular number of states or clock edges after the condition.
    ack_rises = []
    previous = None
    for i, row in enumerate(trace):
        ack = row['outputs'].get('cmd_ack')
        if i > 0 and ack == 1 and previous != 1:
            ack_rises.append((i, row['edge']))
        previous = ack

    # Delimit each contiguous ena-low interval while reset is inactive.
    # These indices describe the observed condition; they are not a latency
    # bound imposed on the design.
    intervals = []
    start = None
    for i, row in enumerate(trace):
        if disabled(row):
            if start is None:
                start = i
        elif start is not None:
            intervals.append((start, i - 1))
            start = None
    if start is not None:
        intervals.append((start, len(trace) - 1))

    if not intervals:
        return (None, None,
                "the routed core-disabled situation licensed by `ena` low while reset is inactive was not observed")

    for start, end in intervals:
        for rise_index, rise_edge in ack_rises:
            if start <= rise_index <= end:
                return (False, rise_edge,
                        '`cmd_ack` rose while `ena` was low; the routed timing signature requires command completion to be delayed during the core-disabled interval')

    for start, end in intervals:
        for rise_index, rise_edge in ack_rises:
            if rise_index <= end:
