            row = trace[rise_index]
            if reset_inactive(row) and row['inputs'].get('ena') != 0:
                return (True, rise_edge,
                        '`cmd_ack` rose after the `ena`-low interval ended; no exact `clk_cnt` latency or state count is assumed')

