def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, throughout, worst

    def holds(cond):
        return lambda row: all(
            row['outputs'].get(port, row['inputs'].get(port)) == value
            for port, value in cond.items()
        )

    def any_of(alternatives):
        predicates = [holds(cond) for cond in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    aborts = any_of([{'nReset': 0}, {'rst': 1}])
    active_wait = lambda row: (
        row['inputs'].get('scl_i') == 0 and
        row['outputs'].get('busy') == 1
    )

    # The wait must not complete with cmd_ack while SCL remains stretched low.
    wait_windows = after(
        trace,
        active_wait,
        until=holds({'scl_i': 1}),
        aborts=aborts,
    )
    no_ack_while_stretched = [
        throughout(
            window,
            lambda row: row['outputs'].get('cmd_ack') != 1,
            after_activation=False,
        )
        for window in wait_windows
    ]

    # The completion indication is postponed until SCL is released. Exact
    # latency and pulse width are intentionally left unspecified.
    completion_windows = after(
        trace,
        active_wait,
        until=TO_END,
        aborts=aborts,
    )
    postponed_completion = [
        eventually(
            window,
            lambda row: (
                row['inputs'].get('scl_i') == 1 and
                row['outputs'].get('cmd_ack') == 1
            ),
            after_activation=False,
            strong=False,
        )
        for window in completion_windows
    ]

    return worst(no_ack_while_stretched + postponed_completion)

