def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, never, worst

    scl_oen_rises = edges(trace, "scl_oen", "rise")
    scl_i_rises = edges(trace, "scl_i", "rise")
    cmd_ack_rises = edges(trace, "cmd_ack", "rise")

    activations = after(
        trace,
        lambda r: (
            r["edge"] in scl_oen_rises
            and r["inputs"].get("scl_i") == 0
            and r["outputs"].get("busy") == 1
        ),
        until=lambda r: r["inputs"].get("scl_i") == 1,
    )

    results = []
    for w in activations:
        results.append(
            never(
                w,
                lambda r: r["edge"] in cmd_ack_rises,
                after_activation=False,
            )
        )

        release_windows = after(
            trace,
            lambda r, opened=w.edge: (
                r["edge"] in scl_i_rises and r["edge"] > opened
            ),
            until=TO_END,
        )
        if release_windows:
            results.append(
                eventually(
                    release_windows[0],
                    lambda r: r["edge"] in cmd_ack_rises,
                    after_activation=False,
                    strong=False,
                )
            )

    return worst(results)

