    if not windows:
        return (None, None, 'the slave-wait condition never occurred: filtered SCL was never held low')

    held_results = [
        throughout(
            w,
            lambda r: r['outputs'].get('cmd_ack') == 0,
            after_activation=False,
        )
        for w in windows
    ]
    held_result = worst(held_results)
    if held_result[0] is False:
        return held_result

    # The routed observation must show the contrasting post-release case too;
    # otherwise a permanently quiet cmd_ack would pass vacuously.
    release_edges = [r['edge'] for r in trace if scl_released(r)]
    if not release_edges:
        return (None, None, 'SCL remained held low; release was not observed')

    release_edge = release_edges[0]
