    scl_oen_rises = edges(trace, 'scl_oen', 'rise')
    scl_i_rises = edges(trace, 'scl_i', 'rise')

    def slave_wait_opens(row):
        return (row['edge'] in scl_oen_rises
                and row['inputs'].get('scl_i') == 0)

    def scl_released(row):
        return row['edge'] in scl_i_rises

    windows = after(trace, slave_wait_opens, until=scl_released)
    if not windows:
        return (None, None,
                'slave-wait activation never occurred: scl_oen did not rise while scl_i was low')

    results = []
    missing_release = []
    missing_completion = []

    for w in windows:
        held = throughout(
            w,
            lambda r: r['outputs'].get('cmd_ack') == 0,
            after_activation=False,
        )
        results.append(held)

        if not w.closed:
            missing_release.append(w.edge)
            continue

        release_rows = [
            r for r in trace
            if r['edge'] > w.edge and scl_released(r)
        ]
        if not release_rows:
            missing_release.append(w.edge)
