        release_edge = release_rows[0]['edge']
        post_release = after(
            trace,
            lambda r, e=release_edge: r['edge'] == e,
            until=TO_END,
        )
        completion = [
            eventually(pw, lambda r: r['outputs'].get('cmd_ack') == 1,
                       after_activation=False, strong=False)
            for pw in post_release
