def decide(trace):
    def busy_rise(i):
        if i < 0 or trace[i]['outputs'].get('busy') != 1:
            return False
        if i == 0:
            return False
        return trace[i - 1]['outputs'].get('busy') == 0

    positive = []
    other = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if row['outputs'].get('busy') != 0:
            continue
        old_sda = prev['inputs'].get('sda_i')
        new_sda = row['inputs'].get('sda_i')
        scl_high = row['inputs'].get('scl_i') == 1
        changed = old_sda != new_sda
        if old_sda == 1 and new_sda == 0 and scl_high:
            positive.append(i)
        elif changed:
            other.append(i)

    if not positive and not other:
        return (None, None, 'no declared-port SDA transition while busy was idle')

    for i in positive:
        rise = next((j for j in range(i, len(trace)) if busy_rise(j)), None)
        if rise is None:
            return (False, trace[i]['edge'], 'filtered SDA-fall/SCL-high START signature was observed, but busy never rose')

    other_checked = False
    for i in other:
        next_positive = next((p for p in positive if p > i), len(trace))
        false_rise = next((j for j in range(i, next_positive) if busy_rise(j)), None)
        if false_rise is not None:
            return (False, trace[false_rise]['edge'], 'busy rose for an SDA transition that was not a falling edge while SCL was high')
        other_checked = True

    if not positive or not other_checked:
        return (None, None, 'only one side of the START-condition observation was exercised')

    return (True, trace[positive[0]]['edge'], 'busy rose for each START signature and did not rise for non-START SDA transitions')

