def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    if not trace:
        return (None, None, 'no trace states; no command sequence was observed')

    ports = ('scl_oen', 'sda_oen')
    first = trace[0].get('outputs', {})
    if any(p not in first for p in ports):
        return (None, None, 'scl_oen and sda_oen are not both present as declared outputs')

    idle = {p: first[p] for p in ports}
    changed = set()
    for i in range(1, len(trace)):
        outputs = trace[i].get('outputs', {})
        previous = trace[i - 1].get('outputs', {})
        for p in ports:
            if outputs.get(p) != previous.get(p):
                changed.add(trace[i]['edge'])

    if not changed:
        return (None, None, 'no START, STOP, READ, or WRITE sequence output departure was observed')

    def aborts(row):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        return (outputs.get('al') == 1 or inputs.get('nReset') == 0 or inputs.get('rst') == 1)

    def begins(row):
        return row['edge'] in changed

    windows = after(trace, begins, until=lambda r: r.get('outputs', {}).get('cmd_ack') == 1,
                    aborts=aborts)

    verdicts = []
    for w in windows:
        for p in ports:
            verdicts.append(eventually(
                w,
                lambda r, port=p: r.get('outputs', {}).get(port) != idle[port],
                after_activation=True,
                strong=False))
    return worst(verdicts)

def decide(trace):
    if len(trace) < 2:
        return (None, None, 'no command-sequence output departure was observed')

    ports = ('scl_oen', 'sda_oen')
    for i in range(1, len(trace)):
        previous = trace[i - 1].get('outputs', {})
        current = trace[i].get('outputs', {})
        changed = [p for p in ports if current.get(p) != previous.get(p)]
        if changed:
            return (True, trace[i].get('edge'),
                    'command-sequence signature observed: ' + ', '.join(changed) +
                    ' departed from its preceding idle output state')

    return (None, None,
            'no START, STOP, READ, or WRITE command-sequence output departure was observed')

