def decide(trace):
    from specflow.refmodel.temporal import edges, worst

    def out(row, port):
        return row['outputs'].get(port)

    def reset_active(row):
        return (row['inputs'].get('nReset') == 0 or
                row['inputs'].get('rst') == 1)

    # No command encoding table is provided.  Use a command-port change as
    # the encoding-independent indication that a command was issued.
    command_edges = edges(trace, 'cmd', 'change')
    attempts = []

    for start_i, row in enumerate(trace):
        if row.get('edge') not in command_edges:
            continue
        if reset_active(row):
            continue

        release_i = None
        # Release is a state requirement: it may already hold at command
        # issue, or may be reached afterwards.  Do not require a transition or
        # a particular latency.
        for i in range(start_i, len(trace)):
            if reset_active(trace[i]):
                break
            if out(trace[i], 'scl_oen') == 1 and out(trace[i], 'sda_oen') == 1:
                release_i = i
                break

        if release_i is None:
            attempts.append((False, row.get('edge'),
                             'START sequence did not reach released SDA and SCL'))
            continue

        start_condition_i = None
        for i in range(release_i + 1, len(trace)):
            if reset_active(trace[i]):
                break
            if (out(trace[i], 'sda_oen') == 0 and
                    out(trace[i], 'scl_oen') == 1):
                start_condition_i = i
                break

        if start_condition_i is None:
            if any(reset_active(r) for r in trace[release_i + 1:]):
                attempts.append((None, None,
                                 'START attempt aborted by reset before SDA was pulled low'))
            else:
                attempts.append((False, trace[release_i]['edge'],
                                 'SDA was not pulled low while SCL remained released high'))
            continue

        scl_low_i = None
        for i in range(start_condition_i + 1, len(trace)):
            if reset_active(trace[i]):
                break
            if out(trace[i], 'scl_oen') == 0:
                scl_low_i = i
                break

        if scl_low_i is None:
            if any(reset_active(r) for r in trace[start_condition_i + 1:]):
                attempts.append((None, None,
                                 'START attempt aborted by reset before SCL was pulled low'))
            else:
                attempts.append((False, trace[start_condition_i]['edge'],
                                 'SCL was not pulled low after the START condition'))
            continue

        ack_i = None
        for i in range(scl_low_i, len(trace)):
            if reset_active(trace[i]):
                break
            if out(trace[i], 'cmd_ack') == 1:
                ack_i = i
                break

        if ack_i is None:
            if any(reset_active(r) for r in trace[scl_low_i:]):
                attempts.append((None, None,
                                 'START attempt aborted by reset before cmd_ack'))
            else:
                attempts.append((False, trace[scl_low_i]['edge'],
                                 'cmd_ack was not asserted after SCL was pulled low'))
        else:
            attempts.append((True, trace[ack_i]['edge'],
                             'START sequence ordered: SDA/SCL released, SDA low while SCL high, SCL low, then cmd_ack high'))

    if not attempts:
        return (None, None, 'the START command never occurred in this trace')
    return worst(attempts)

def decide(trace):
    from specflow.refmodel.temporal import edges, worst

    def out(row, port):
        return row.get('outputs', {}).get(port)

    def reset(row):
        return (row.get('inputs', {}).get('nReset') == 0 or
                row.get('inputs', {}).get('rst') == 1)

    def edge_of(row):
        return row.get('edge')

    def aborted(begin, end=None):
        stop = len(trace) if end is None else end
        return any(reset(trace[i]) for i in range(begin, stop))

    # There is no command encoding table.  A command-port change is therefore
    # only an encoding-independent trigger; the output signature is used when
    # the command is already present in the first trace state.
    command_changes = edges(trace, 'cmd', 'change')
    starts = []

    if command_changes:
        for i, row in enumerate(trace):
            if edge_of(row) not in command_changes or reset(row):
                continue
            starts.append(i)
    else:
        # Fallback signature: SDA is pulled low while SCL remains released.
        # This is the declared output signature of the START situation, not an
        # invented numeric command encoding.
        for i in range(1, len(trace)):
            if reset(trace[i]):
                continue
            if (out(trace[i - 1], 'scl_oen') == 1 and
                    out(trace[i - 1], 'sda_oen') == 1 and
                    out(trace[i], 'scl_oen') == 1 and
                    out(trace[i], 'sda_oen') == 0):
                starts.append(i - 1)

    if not starts:
        return (None, None, 'the START command or its encoding-independent output signature never occurred')

    verdicts = []
    for start in starts:
        if reset(trace[start]):
            continue

        release = None
        for i in range(start, len(trace)):
            if reset(trace[i]):
                break
            if (out(trace[i], 'scl_oen') == 1 and
                    out(trace[i], 'sda_oen') == 1):
                release = i
                break

        if release is None:
            if aborted(start):
                verdicts.append((None, None, 'START attempt aborted by reset before SDA and SCL were released'))
            else:
                verdicts.append((False, edge_of(trace[start]),
                                 'START sequence did not reach released SDA and SCL'))
