            if reset(trace[i]):
                break
            if (out(trace[i], 'scl_oen') == 1 and
                    out(trace[i], 'sda_oen') == 0):
                sda_low = i
                break

        if sda_low is None:
            if aborted(release + 1):
                verdicts.append((None, None,
                                 'START attempt aborted by reset before SDA was pulled low'))
            else:
                verdicts.append((False, edge_of(trace[release]),
                                 'SDA was not pulled low while SCL remained released high'))
            continue

        scl_low = None
        for i in range(sda_low + 1, len(trace)):
            if reset(trace[i]):
