    def any_of(alternatives):
        predicates = [holds(cond) for cond in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    # With no cmd encoding table, recognize the WRITE signature from declared
    # ports: SDA is set according to din while SCL is released, followed by the
    # transition that pulls SCL low again.
    completion_transitions = []
