        if not started:
            i += 1
            continue

        rows = []
        duration = 0
        j = i
        while j < len(trace):
            current = trace[j]
            if (current['inputs'].get('scl_i') != 1 or
                    current['inputs'].get('sda_i') != 0):
                break
            rows.append((j, current))
            duration += current['held']
            j += 1

        episodes.append({'start': i, 'rows': rows, 'duration': duration})
        i = j

    if len(episodes) < 2:
        return (None, None,
                'the short and sustained SDA-low disturbances were not both exercised')

    shortest = min(episodes, key=lambda e: e['duration'])
    longest = max(episodes, key=lambda e: e['duration'])
    if shortest is longest or shortest['duration'] == longest['duration']:
        return (None, None,
                'no distinguishable short and sustained disturbance durations were observed')

    # Short disturbance: filtering must prevent busy from rising.
    for index, row in shortest['rows']:
        if row['outputs'].get('busy') != 0:
            return (False, row['edge'],
                    'busy rose for the short SDA-low disturbance; the requirement says it must remain low')

    # Sustained transition: filtering must allow the recognized START to make
    # busy rise.  Require an observed 0->1 transition, not merely a high level.
    for index, row in longest['rows']:
        if row['outputs'].get('busy') == 1:
            before = trace[index - 1]['outputs'].get('busy') if index > 0 else None
            if before == 0:
                return (True, row['edge'],
                        'busy stayed low for the short disturbance and rose for the sustained SDA falling transition')

    return (False, trace[longest['start']]['edge'],
            'busy did not rise for the sustained SDA falling transition')

def decide(trace):
    episodes = []
    i = 1
    while i < len(trace):
        prev = trace[i - 1]
        row = trace[i]
        falling_start = (
            prev['inputs'].get('scl_i') == 1 and
            row['inputs'].get('scl_i') == 1 and
            prev['inputs'].get('sda_i') == 1 and
            row['inputs'].get('sda_i') == 0
        )
        if not falling_start:
            i += 1
            continue

        j = i
        duration = 0
        while j < len(trace):
            current = trace[j]
            if (current['inputs'].get('scl_i') != 1 or
                    current['inputs'].get('sda_i') != 0):
                break
            duration += current['held']
            j += 1

        episodes.append({
            'start': i,
            'end': j,
            'duration': duration,
        })
        i = j

    if len(episodes) < 2:
        return (None, None,
                'short and sustained SDA-low disturbances were not both exercised')

    short = min(episodes, key=lambda e: e['duration'])
    sustained = max(episodes, key=lambda e: e['duration'])
    if short['duration'] >= sustained['duration']:
        return (None, None,
                'no distinguishable short and sustained disturbance durations were observed')

    for k in range(short['start'], short['end']):
        if trace[k]['outputs'].get('busy') != 0:
            return (False, trace[k]['edge'],
                    'busy rose for the shorter SDA-low disturbance; the route says filtering must keep busy low')

    rise_edge = None
    for k in range(sustained['start'], len(trace)):
        if trace[k]['outputs'].get('busy') != 1:
            continue
        before = trace[k - 1]['outputs'].get('busy') if k > 0 else None
        if before == 0:
            rise_edge = trace[k]['edge']
            break

    if rise_edge is None:
        return (False, trace[sustained['start']]['edge'],
                'busy did not rise for the longer sustained SDA falling transition; no response latency is specified')

    return (True, rise_edge,
            'busy stayed low for the shorter disturbance and rose after the longer sustained SDA falling transition')

