def decide(trace):
    responded = []
    rejected = []

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        old_sda = prev['inputs'].get('sda_i')
        new_sda = row['inputs'].get('sda_i')
        if old_sda == new_sda or row['inputs'].get('scl_i') != 1:
            continue

        fall = old_sda == 1 and new_sda == 0
        rise = old_sda == 0 and new_sda == 1
        busy = row['outputs'].get('busy')
        if fall and busy != 0:
            continue
        if rise and busy != 1:
            continue

        expected_busy = 1 if fall else 0
        found_response = False
        before_next_sda_change = True
        for j in range(i + 1, len(trace)):
            later = trace[j]
            if j > i + 1 and later['inputs'].get('sda_i') != trace[j - 1]['inputs'].get('sda_i'):
                before_next_sda_change = False
                break
            if later['outputs'].get('busy') == expected_busy:
                found_response = True
                break

        if found_response:
            responded.append((row['edge'], 'START' if fall else 'STOP'))
        elif not before_next_sda_change:
            rejected.append((row['edge'], 'glitch'))

    if not responded and not rejected:
        return (None, None, 'no qualifying majority-filter signature occurred in this trace')
    if not responded:
        return (None, rejected[0][0], 'only non-responding SDA transitions were observed; no filtered response was exercised')
    if not rejected:
        return (None, responded[0][0], 'only responding SDA transitions were observed; no single-sample rejection was exercised')

    return (True, None, f'majority-filter signature observed: {len(responded)} responding transition(s) and {len(rejected)} rejected glitch transition(s)')

