def decide(trace):
    # dout is the declared routed observation, but its behavior is licensed
    # by REQ-0036 rather than by this obligation.
    _has_declared_observation = any('dout' in row.get('outputs', {}) for row in trace)
    return (None, None, 'the obligation states no independently observable effect; dout is routed through REQ-0036')

def decide(trace):
    def rises(port):
        result = []
        for i in range(1, len(trace)):
            before = trace[i - 1].get('inputs', {}).get(port)
            now = trace[i].get('inputs', {}).get(port)
            if before == 0 and now == 1:
                result.append(i)
        return result

    scl_rises = rises('scl_i')
    if not scl_rises:
        return (None, None, 'no rising scl_i sampling signature occurred; the filtered-SCL situation was not exercised')

    # Each rising-SCL sampling situation must eventually be represented at dout.
    # No fixed edge count is assumed; effect_follows is false, so the trigger
    # row is also a valid observation row.
    for i in scl_rises:
        sampled_sda = trace[i].get('inputs', {}).get('sda_i')
        found = False
        for row in trace[i:]:
            if row.get('outputs', {}).get('dout') == sampled_sda:
                found = True
                break
        if not found:
            if trace[-1].get('index') == trace[i].get('index'):
                return (None, trace[i].get('edge'), 'the sampling window is incomplete at the end of the trace')
            return (False, trace[i].get('edge'), 'dout did not reach the stable filtered SDA value after a rising filtered-SCL signature')

    # The routed observation must not show a new capture in the absence of a
    # sampling trigger. A dout transition is licensed only after a prior rise.
    for i in range(1, len(trace)):
        old = trace[i - 1].get('outputs', {}).get('dout')
        new = trace[i].get('outputs', {}).get('dout')
        if old != new and not any(rise < i for rise in scl_rises):
            return (False, trace[i].get('edge'), 'dout changed without a preceding rising filtered-SCL sampling signature')

    return (True, None, 'dout reflects the stable sampled SDA value for each rising filtered-SCL signature and does not change without such a trigger')

