def decide(trace):
    def sda_edges(level):
        result = []
        for i in range(1, len(trace)):
            prev = trace[i - 1]['inputs'].get('sda_i')
            cur = trace[i]['inputs'].get('sda_i')
            if prev != cur and cur == level:
                result.append(i)
        return result

    starts = [i for i in sda_edges(0)
              if trace[i]['inputs'].get('scl_i') == 1]
    stops = [i for i in sda_edges(1)
             if trace[i]['inputs'].get('scl_i') == 1]
    unrelated = [i for i in range(1, len(trace))
                 if trace[i]['inputs'].get('sda_i') != trace[i - 1]['inputs'].get('sda_i')
                 and trace[i]['inputs'].get('scl_i') == 0]

    if not starts and not stops:
        return (None, None,
                'no filtered-SDA transition while filtered SCL was high; the routed situation was not exercised')
    if not unrelated:
        return (None, None,
                'no SDA transition while filtered SCL was low; the routed otherwise case was not exercised')

    for i in starts:
        before = trace[i]['outputs'].get('busy')
        for j in range(i + 1, len(trace)):
            value = trace[j]['outputs'].get('busy')
            if value != before:
                if value != 1:
                    return (False, trace[j]['edge'],
                            'after an SDA falling transition while SCL was high, busy changed away from 1 instead of reflecting START detection')
                break
        else:
            return (False, trace[i]['edge'],
                    'after an SDA falling transition while SCL was high, busy did not change to 1')

    for i in stops:
        before = trace[i]['outputs'].get('busy')
        for j in range(i + 1, len(trace)):
            value = trace[j]['outputs'].get('busy')
            if value != before:
                if value != 0:
                    return (False, trace[j]['edge'],
                            'after an SDA rising transition while SCL was high, busy changed away from 0 instead of reflecting STOP detection')
                break
        else:
            return (False, trace[i]['edge'],
                    'after an SDA rising transition while SCL was high, busy did not change to 0')

    positive = sorted(starts + stops)
    for i in unrelated:
        before = trace[i]['outputs'].get('busy')
        next_positive = next((p for p in positive if p > i), len(trace))
        for j in range(i, next_positive):
            if trace[j]['outputs'].get('busy') != before:
                return (False, trace[j]['edge'],
                        'busy changed for an SDA transition while SCL was low, where no START/STOP detection is specified')

    return (True, None,
            'busy reflected both high-SCL START/STOP transitions and remained unchanged for the low-SCL SDA transition case')

def decide(trace):
    # dSCL/dSDA are internal.  Observe the licensed routed signature through
    # the declared busy output and the declared SDA/SCL input signature.
    high_cases = []
    low_cases = []

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        old_sda = prev['inputs'].get('sda_i')
        new_sda = row['inputs'].get('sda_i')
        scl_high = row['inputs'].get('scl_i') == 1
        if old_sda == new_sda:
            continue
        if scl_high:
            # SDA falling while SCL is high is START (busy rises); rising is
            # STOP (busy falls).  Require the routed output transition, not
            # merely the level, so ordinary busy behaviour cannot satisfy it.
            expected = 1 if new_sda < old_sda else 0
            busy_edge = None
            for j in range(i + 1, len(trace)):
                before = trace[j - 1]['outputs'].get('busy')
                after = trace[j]['outputs'].get('busy')
                if before != after and after == expected:
                    busy_edge = trace[j]['edge']
                    break
            high_cases.append((row['edge'], busy_edge, expected))
        else:
            # For an SDA transition while SCL is low, busy must remain
            # unchanged until the next SDA transition.  Without a later bus
            # transition there is no bounded observation of this negative case.
            end = None
            for j in range(i + 1, len(trace)):
                p = trace[j - 1]['inputs'].get('sda_i')
                q = trace[j]['inputs'].get('sda_i')
                if p != q:
                    end = j
                    break
            if end is None:
                low_cases.append((row['edge'], None))
            else:
                initial = row['outputs'].get('busy')
                changed = any(
                    trace[j]['outputs'].get('busy') != initial
                    for j in range(i + 1, end)
                )
                low_cases.append((row['edge'], not changed))

    if not high_cases and not low_cases:
        return (None, None, 'no SDA transition was observed')
    if not high_cases or not low_cases:
        return (None, None, 'only one side of the routed busy signature was observed')

    for activation_edge, busy_edge, expected in high_cases:
        if busy_edge is None:
            return (False, activation_edge,
                    f'busy did not make the expected transition to {expected} after the high-SCL SDA transition')

    for activation_edge, unchanged in low_cases:
        if unchanged is None:
            return (None, activation_edge,
                    'the low-SCL SDA case was observed but the trace ended before its negative observation was bounded')
        if not unchanged:
            return (False, activation_edge,
                    'busy changed for an SDA transition while SCL was low')

    return (True, None, 'both routed cases were observed: high-SCL SDA transitions changed busy appropriately and low-SCL transitions did not')

def decide(trace):
    # The internal dSCL/dSDA signals are not declared ports.  Use the licensed
    # busy route as a signature of the filtered-bus situation instead.
    events = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        old_sda = prev['inputs'].get('sda_i')
        new_sda = row['inputs'].get('sda_i')
        if old_sda == new_sda:
            continue
        # The raw declared bus inputs are the available signature of a
        # filtered SDA transition; no filter latency is assumed.
        scl_high = row['inputs'].get('scl_i') == 1
        events.append((i, scl_high, new_sda < old_sda))

    if not events:
        return (None, None, 'no SDA transition was observed; the routed filtered-bus situation did not occur')

    high_cases = []
    low_cases = []
    for n, (i, scl_high, falling) in enumerate(events):
        end = events[n + 1][0] if n + 1 < len(events) else len(trace)
        if scl_high:
            # Falling SDA while SCL is high is START; rising SDA is STOP.
            expected = 1 if falling else 0
            high_cases.append((i, end, expected))
        else:
            low_cases.append((i, end))

    if not high_cases or not low_cases:
        return (None, trace[events[0][0]]['edge'],
                'only one side of the routed busy signature was observed')

    # A transition at the start of the interval is permitted: the
    # specification does not state whether filtering and observation are
    # represented in the same distinct state or a later one.
    for start, end, expected in high_cases:
        seen = any(
            trace[j]['outputs'].get('busy') == expected
            for j in range(start, end)
        )
        if not seen:
            return (False, trace[start]['edge'],
                    f'busy did not reach {expected} for the START/STOP signature before the next SDA transition')

    for start, end in low_cases:
        if end == len(trace):
            return (None, trace[start]['edge'],
                    'the low-SCL routed case was observed, but the trace ended before its unchanged interval was bounded')
        initial = trace[start]['outputs'].get('busy')
        changed = any(
            trace[j]['outputs'].get('busy') != initial
            for j in range(start, end)
        )
        if changed:
            return (False, trace[start]['edge'],
                    'busy changed for an SDA transition while the filtered SCL signature was low')

    return (True, None,
            'both routed cases were observed: high-SCL SDA transitions reached the corresponding busy state and low-SCL transitions left busy unchanged')

