def decide(trace):
    # A START is an SDA falling transition while SCL is high.
    starts = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if (prev['inputs'].get('sda_i') == 1
                and row['inputs'].get('sda_i') == 0
                and row['inputs'].get('scl_i') == 1):
            starts.append(i)

    if not starts:
        return (None, None,
                'no START activation: sda_i did not fall while scl_i was high')

    # Positive side of the routed signature: busy must be high at or after
    # each qualifying START.  The specification fixes no latency.
    for i in starts:
        seen_busy = any(r['outputs'].get('busy') == 1 for r in trace[i:])
        if not seen_busy:
            return (False, trace[i]['edge'],
                    'START detected by sda_i falling while scl_i was high, '
                    'but busy never asserted')

    # Negative side of the routed signature: a busy assertion must not occur
    # without a qualifying START since busy was last low.
    last_busy_low = -1
    for i, row in enumerate(trace):
        busy = row['outputs'].get('busy')
        if busy == 0:
            last_busy_low = i
        elif busy == 1:
            qualified = any(last_busy_low < s <= i for s in starts)
            if i > 0 and trace[i - 1]['outputs'].get('busy') != 1 and not qualified:
                return (False, row['edge'],
                        'busy asserted without sda_i falling while scl_i was high')

    return (True, trace[starts[0]]['edge'],
            f'{len(starts)} START condition(s) observed through busy')

