def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, edges, worst

    rises = edges(trace, "sda_i", "rise")

    def stop_activation(row):
        return (row["edge"] in rises
                and row["inputs"].get("scl_i") == 1
                and row["outputs"].get("busy") == 1)

    def closes_on_scl_low(row):
        return row["inputs"].get("scl_i") == 0

    stop_windows = after(trace, stop_activation, until=closes_on_scl_low)
    stop_verdicts = [
        eventually(
            window,
            lambda row: row["outputs"].get("busy") == 0,
            after_activation=True,
            strong=True,
        )
        for window in stop_windows
    ]

    # Check the alternative route case: while busy is high and SCL is high,
    # if SDA does not rise, busy must remain high.  Group consecutive distinct
    # states having SCL high and no SDA rising transition.
    quiet_segments = []
    current = []
    for row in trace:
        quiet = (row["inputs"].get("scl_i") == 1
                 and row["edge"] not in rises)
        if quiet:
            current.append(row)
        elif current:
            quiet_segments.append(current)
            current = []
    if current:
        quiet_segments.append(current)

    no_stop_seen = False
    no_stop_failure = None
    no_stop_edge = None
    for segment in quiet_segments:
        busy_positions = [i for i, row in enumerate(segment)
                          if row["outputs"].get("busy") == 1]
        if not busy_positions:
            continue
        no_stop_seen = True
        first_busy = busy_positions[0]
        for row in segment[first_busy:]:
            if row["outputs"].get("busy") != 1:
                no_stop_failure = (False, row["edge"],
                                   "busy did not remain high while SDA did not transition low-to-high with SCL high")
                no_stop_edge = row["edge"]
                break
        if no_stop_failure is not None:
            break

    stop_seen = bool(stop_windows)
    if stop_seen:
        stop_result = worst(stop_verdicts)
        if stop_result[0] is False:
            return stop_result
    else:
        stop_result = (None, None, "no STOP transition was observed")

    if no_stop_failure is not None:
        return no_stop_failure

    if not stop_seen or not no_stop_seen:
        missing = []
        if not stop_seen:
            missing.append("STOP case")
        if not no_stop_seen:
            missing.append("no-STOP case")
        return (None, None, "only one route case was exercised; missing " + " and ".join(missing))

    return (True, None, "busy cleared after the STOP transition and remained high when no STOP transition occurred")

