def decide(trace):
    # The route condition is the available port-level signature of the
    # stretching/synchronization situation.  Detect its initiating change
    # rather than treating an initial level as an action.
    starts = []
    for i, row in enumerate(trace):
        if i == 0:
            continue
        prev = trace[i - 1]
        oen = row['outputs'].get('scl_oen')
        prev_oen = prev['outputs'].get('scl_oen')
        scl_i = row['inputs'].get('scl_i')
        prev_scl_i = prev['inputs'].get('scl_i')
        released_while_low = (prev_oen != 1 and oen == 1 and scl_i == 0)
        external_fall = (prev_scl_i == 1 and scl_i == 0 and oen == 1)
        if released_while_low or external_fall:
            starts.append(i)

    if not starts:
        return (None, None,
                'clock-stretching or synchronization condition never occurred')

    completed = []
    for start in starts:
        release = None
        for j in range(start, len(trace)):
            row = trace[j]
            if row['inputs'].get('scl_i') == 1:
                release = j
                break
            if row['outputs'].get('scl_oen') != 1:
                return (False, row['edge'],
                        'scl_oen returned low while external scl_i was held low; '
                        'the required stretching/synchronization wait was not handled')

        if release is None:
            continue

        returned = None
        for j in range(release, len(trace)):
            if trace[j]['outputs'].get('scl_oen') == 0:
                returned = j
                break
        if returned is not None:
            completed.append((start, returned))

    if not completed:
        return (None, None,
                'the low-scl_i condition occurred but the trace ended before '
                'both the external release and the subsequent scl_oen return')

    end = completed[0][1]
    return (True, trace[end]['edge'],
            'scl_oen remained high while external scl_i was low and returned low '
            'after scl_i was released, with no fixed latency assumed')

def decide(trace):
    starts = []
    for i, row in enumerate(trace):
        if i == 0:
            continue
        prev = trace[i - 1]
        oen = row['outputs'].get('scl_oen')
        prev_oen = prev['outputs'].get('scl_oen')
        scl_i = row['inputs'].get('scl_i')
        prev_scl_i = prev['inputs'].get('scl_i')

        # The route identifies the situation as SCL being released, or an
        # external SCL fall while it is already released.  Do not require
        # scl_i to be low on the release transition itself.
        released = prev_oen != 1 and oen == 1
        external_fall = prev_scl_i == 1 and scl_i == 0 and oen == 1
        if released or external_fall:
            starts.append(i)

    if not starts:
        return (None, None,
                'the declared scl_oen/scl_i clock-stretching or synchronization '
                'signature never occurred')

    saw_stretch = False
    saw_normal = False

    for start in starts:
        stretching = False
        completed = False
        for j in range(start + 1, len(trace)):
            row = trace[j]
            oen = row['outputs'].get('scl_oen')
            scl_i = row['inputs'].get('scl_i')

            if not stretching and scl_i == 0:
                stretching = True
                saw_stretch = True

            if stretching:
                if scl_i == 0:
                    if oen != 1:
                        return (False, row['edge'],
                                'scl_oen returned low while external scl_i remained low; '
                                'clock stretching or synchronization was not handled')
                elif oen == 0:
                    completed = True
                    break
            elif oen == 0:
                saw_normal = True
                completed = True
                break

        if not completed:
            continue

    if saw_stretch and saw_normal:
        return (True, None,
                'scl_oen held high through externally low scl_i and also returned low '
                'in the ordinary released-SCL case; no fixed latency assumed')
    if saw_stretch:
        return (None, None,
