def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout

    def _inputs(row):
        return row.get('inputs', {})

    def _outputs(row):
        return row.get('outputs', {})

    scl_oen_rises = edges(trace, 'scl_oen', 'rise')
    scl_i_rises = edges(trace, 'scl_i', 'rise')
    ack_rises = edges(trace, 'cmd_ack', 'rise')

    # The activation is the release action: scl_oen must rise while scl_i is low.
    wait_windows = after(
        trace,
        lambda r: r['edge'] in scl_oen_rises and _inputs(r).get('scl_i') == 0,
        until=lambda r: _inputs(r).get('scl_i') == 1
    )

    if not wait_windows:
        return (None, None, 'SCL-release-while-low activation never occurred')

    wait_verdicts = [
        throughout(
            w,
            lambda r: r['edge'] not in ack_rises,
            after_activation=False
        )
        for w in wait_windows
    ]

    # Check the other side of the routed observation only for SCL rises that
    # follow a qualifying release, so ordinary cmd_ack behaviour alone cannot
    # satisfy this requirement.
    post_release_windows = after(
        trace,
        lambda r: (
            r['edge'] in scl_i_rises
            and any(
                e < r['edge']
                for e in scl_oen_rises
                if any(
                    x['edge'] == e and _inputs(x).get('scl_i') == 0
                    for x in trace
                )
            )
        ),
        until=TO_END
    )

    post_verdicts = [
        eventually(
            w,
            lambda r: r['edge'] in ack_rises,
            after_activation=True,
            strong=False
        )
        for w in post_release_windows
    ]

    verdicts = wait_verdicts + post_verdicts
    bad = [v for v in verdicts if v[0] is False]
    if bad:
        return bad[0]

    if wait_verdicts and all(v[0] is True for v in wait_verdicts) and post_verdicts and all(v[0] is True for v in post_verdicts):
        return (True, None, 'cmd_ack remained postponed while scl_oen was released with scl_i low, then rose after scl_i rose')

    return (None, None, 'only one side of the routed cmd_ack signature was observed')

