def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, edges, throughout, worst

    def stalled(row):
        return (row['outputs'].get('scl_oen') == 1 and
                row['inputs'].get('scl_i') == 0)

    # This is a level signature, not a command encoding: the controller has
    # released SCL while the observed bus level remains low.
    windows = after(trace, stalled, until=WHILE_ACTIVE)
    if not windows:
        return (None, None, 'the SCL-held-low activation never occurred')

    ack_rises = edges(trace, 'cmd_ack', 'rise')

    # A new completion pulse must not occur while the bus participant is
    # holding SCL low.  The routed observation is about postponement, so an
    # existing level is not treated as a new pulse.
    verdicts = [
        throughout(
            w,
            lambda r: r['edge'] not in ack_rises,
            after_activation=False
        )
        for w in windows
    ]
    bad = [v for v in verdicts if v[0] is False]
    if bad:
        return bad[0]

    # The route describes a difference at cmd_ack.  Without evidence of the
    # ordinary completion side, the trace cannot establish that this was a
    # postponed completion rather than a design that never completes.
    normal_completion = [
        r for r in trace
        if r['edge'] in ack_rises and not stalled(r)
    ]
    if not normal_completion:
        return (None, None,
                'SCL-held-low was observed, but no normal cmd_ack completion was observed for comparison')

    return (True, normal_completion[0]['edge'],
            'cmd_ack was postponed while scl_oen was released and scl_i remained low; normal completion was observed outside that condition')

