def decide(trace):
    activations = []
    for i, row in enumerate(trace):
        if i == 0:
            continue
        prev = trace[i - 1]
        out = row.get('outputs', {})
        prev_out = prev.get('outputs', {})
        inp = row.get('inputs', {})
        if (prev_out.get('busy') != 1 and out.get('busy') == 1
                and inp.get('nReset') == 1
                and inp.get('ena') == 1):
            activations.append(i)

    if not activations:
        return (None, None,
                'no command-sequence activation observed: busy never rose while nReset was released and ena was enabled')

    for start in activations:
        clk_cnt_value = trace[start].get('inputs', {}).get('clk_cnt')
        end = len(trace) - 1
        for j in range(start + 1, len(trace)):
            if trace[j].get('outputs', {}).get('busy') != 1:
                end = j
                break

        ack_rise = None
        for j in range(start + 1, end + 1):
            ack = trace[j].get('outputs', {}).get('cmd_ack')
            prev_ack = trace[j - 1].get('outputs', {}).get('cmd_ack')
            if prev_ack != 1 and ack == 1:
                ack_rise = j
                break

        if ack_rise is not None:
            return (True, trace[ack_rise].get('edge'),
                    f'cmd_ack rose after the command-sequence activation with fixed clk_cnt={clk_cnt_value}')

        if end < len(trace) - 1:
            return (False, trace[end].get('edge'),
                    f'no cmd_ack pulse occurred before command completion for fixed clk_cnt={clk_cnt_value}')

    return (None, None,
            'command activation was observed but the trace ended before its completion acknowledgment')

