def decide(trace):
    changes = []
    boundary_changes = []
    nonboundary_holds = False
    boundary_seen = False

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_out = prev.get('outputs', {})
        out = row.get('outputs', {})
        prev_in = prev.get('inputs', {})
        inp = row.get('inputs', {})

        # Use busy as the declared-output signature that a command sequence is active.
        active = prev_out.get('busy') == 1 and out.get('busy') == 1
        if not active:
            continue

        scl_changed = prev_out.get('scl_oen') != out.get('scl_oen')
        timing_boundary = inp.get('clk_cnt') == 0

        if timing_boundary:
            boundary_seen = True
            if scl_changed:
                boundary_changes.append(row)
        elif not scl_changed:
            nonboundary_holds = True
        elif scl_changed:
            changes.append(row)

    if changes:
        row = changes[0]
        return (False, row.get('edge'),
                'scl_oen advanced before the clk_cnt-derived timing boundary')

    if not boundary_seen or not boundary_changes:
        return (None, None,
                'no active command-sequence scl_oen advance was observed at a clk_cnt expiration boundary')

    if not nonboundary_holds:
        return (None, boundary_changes[0].get('edge'),
                'a timing-boundary scl_oen advance was observed, but no preceding non-boundary hold was exercised')

    return (True, boundary_changes[0].get('edge'),
            'scl_oen held before the clk_cnt-derived boundary and advanced only at that boundary')

