def decide(trace):
    active_transitions = []

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_out = prev.get('outputs', {})
        out = row.get('outputs', {})
        prev_in = prev.get('inputs', {})
        inp = row.get('inputs', {})

        # `busy` is the declared-output signature that a command sequence is active.
        if out.get('busy') != 1:
            continue

        # The FSM's phase advance is observable as an action on scl_oen.
        scl_changed = prev_out.get('scl_oen') != out.get('scl_oen')
        if not scl_changed:
            continue

        # Do not assume a numeric terminal value for clk_cnt.  A change in the
        # declared counter is the available signature of the derived timing tick.
        counter_changed = prev_in.get('clk_cnt') != inp.get('clk_cnt')
        active_transitions.append((row, counter_changed))

    if not active_transitions:
        return (None, None,
                'no active command-sequence scl_oen phase advance was observed; the clk_en-controlled transition was not exercised')

    for row, counter_changed in active_transitions:
        if not counter_changed:
            return (False, row.get('edge'),
                    'scl_oen advanced during an active command sequence without a clk_cnt timing-boundary change, contrary to "only when clk_en is asserted"')

