def decide(trace):
    # The command encoding is unspecified, so identify the WRITE high phase
    # from its declared output signature and the data-bit input.
    def in_high_phase(row):
        return (row['outputs'].get('scl_oen') == 1 and
                row['outputs'].get('sda_oen') == row['inputs'].get('din'))

    windows = []
    i = 0
    while i < len(trace):
        if not in_high_phase(trace[i]):
            i += 1
            continue
        start = i
        while i < len(trace) and in_high_phase(trace[i]):
            i += 1
        windows.append(trace[start:i])

    if not windows:
        return (None, None,
                'stable WRITE high-phase signature never occurred')

    saw_low = False
    saw_high = False
    first_bad = None
    bad_detail = None

    for window in windows:
        for row in window:
            sda_i = row['inputs'].get('sda_i')
            al = row['outputs'].get('al')
            if sda_i == 0:
                saw_low = True
                if al != 1 and first_bad is None:
                    first_bad = row['edge']
                    bad_detail = (
                        'during the stable WRITE high phase with filtered '
                        'sda_i low, al was not asserted')
            elif sda_i == 1:
                saw_high = True
                if al != 0 and first_bad is None:
                    first_bad = row['edge']
                    bad_detail = (
                        'during the stable WRITE high phase with filtered '
                        'sda_i high, al was not deasserted')

    if first_bad is not None:
        return (False, first_bad, bad_detail)
    if not saw_low or not saw_high:
        return (None, None,
                'the WRITE high phase showed only one side of the al route; '
                'both sda_i-low and sda_i-high cases are needed')

    return (True, None,
            'al asserted for filtered sda_i low and remained deasserted for '
            'filtered sda_i high during the stable WRITE high phase')

