        released_low = [r for r in rows
                        if r['outputs'].get('sda_oen') == 1 and
                           r['inputs'].get('sda_i') == 0]
        released_high = [r for r in rows
                         if r['outputs'].get('sda_oen') == 1 and
                            r['inputs'].get('sda_i') == 1]

