    if not idle_rows:
        return (None, None, 'the idle declared-port signature never occurred')

    active_by_cmd = {}
    for pos in idle_rows:
        cmd = trace[pos].get('inputs', {}).get('cmd')
        j = pos + 1
        while j < len(trace) and idle_signature(trace[j]):
            j += 1
        if j < len(trace):
            out = trace[j].get('outputs', {})
            if out.get('scl_oen') != 1:
                active_by_cmd.setdefault(cmd, trace[j]['edge'])

    if len(active_by_cmd) < 4:
        return (None, None,
                'fewer than four distinct cmd values showed the licensed command-activity signature; '
                'the remaining command encodings are not exercised in this trace')

