    # No command encoding is declared, so do not invent numeric START/STOP/
    # READ/WRITE values.  Use command transitions as the broad stimulus-side
    # signature of a command attempt.
    attempts = []
    previous_cmd = object()
    for row in trace:
        cmd = row.get('inputs', {}).get('cmd')
        if cmd != previous_cmd and row.get('outputs', {}).get('cmd_ack') == 0:
            attempts.append(row)
        previous_cmd = cmd

    if not attempts:
        return (None, None, 'no command attempt was observable without assuming a cmd encoding')

    for attempt in attempts:
        start = attempt['index']
        prior_ack = attempt.get('outputs', {}).get('cmd_ack')
        for row in trace[start + 1:]:
            ack = row.get('outputs', {}).get('cmd_ack')
            if prior_ack == 0 and ack == 1:
                return (True, row['edge'], 'cmd_ack rose after a command attempt, the declared signature of entering a command sequence')
