def decide(trace):
    active = False
    saw_sequence = False
    relevant = []
    aborted = False

    for row in trace:
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        reset = inputs.get('nReset') == 0 or inputs.get('rst') == 1
        arbitration_lost = outputs.get('al') == 1

        if reset or arbitration_lost:
            if active:
                aborted = True
            active = False
            continue

        busy = outputs.get('busy') == 1
        ack = outputs.get('cmd_ack') == 1

        if busy:
            active = True
            saw_sequence = True

        if ack and (active or busy):
            relevant.append(row)
            active = False

    if not saw_sequence or not relevant:
        return (None, None, 'no non-aborted command sequence completion was observable')

    for row in relevant:
        held = row.get('held')
        if held != 1:
            return (
                False,
                row.get('edge'),
                f"cmd_ack was high for {held} clk edges at sequence completion; expected exactly one"
            )

    return (
        True,
        relevant[-1].get('edge'),
        f"all {len(relevant)} observed non-aborted sequence completion acknowledgement(s) lasted exactly one clk edge"
    )

