def decide(trace):
    rises = []
    for i in range(1, len(trace)):
        before = trace[i - 1]['outputs'].get('cmd_ack')
        current = trace[i]['outputs'].get('cmd_ack')
        if before == 0 and current == 1:
            rises.append(i)

    if not rises:
        return (None, None, 'cmd_ack acknowledge pulse was not observed; operation completion was not exercised')

    for i in rises:
        for j in range(i + 1, len(trace)):
            if trace[j]['outputs'].get('cmd_ack') == 0:
                return (True, trace[j]['edge'], 'cmd_ack rose at operation completion and later deasserted, forming an acknowledge pulse')
